QT_ISI(8,{"900":["(Kalau sekiranya Kami turunkan malaikat kepada mereka, dan orang-orang yang telah mati berbicara dengan mereka) seperti apa yang telah mereka minta (dan Kami kumpulkan pula) Kami himpunkan pula (segala sesuatu ke hadapan mereka) dibaca dengan damah kedua huruf permulaannya, jamak dari Lafal qabiil yakni gelombang demi gelombang. Dibaca kasrah huruf qaf-nya serta dibaca fatah huruf ba-nya; artinya: secara terang-terangan sehingga mereka dapat menyaksikan kebenaranmu (niscaya mereka tidak juga akan beriman) karena hal itu telah diketahui oleh Allah sebelumnya (kecuali) melainkan (jika Allah menghendaki) mereka beriman, maka baru mereka dapat beriman (akan tetapi kebanyakan mereka tidak mengetahui) tentang hal itu.",[["۞ وَلَوْ","And (even) if"],["أَنَّنَا","[that] We (had)"],["نَزَّلْنَآ","[We] sent down"],["إِلَيْهِمُ","to them"],["ٱلْمَلَـٰٓئِكَةَ","the Angels"],["وَكَلَّمَهُمُ","and spoken to them"],["ٱلْمَوْتَىٰ","the dead"],["وَحَشَرْنَا","and We gathered"],["عَلَيْهِمْ","before them"],["كُلَّ","every"],["شَىْءٍۢ","thing"],["قُبُلًۭا","face to face"],["مَّا","not"],["كَانُوا۟","they were"],["لِيُؤْمِنُوٓا۟","to believe"],["إِلَّآ","unless"],["أَن","[that]"],["يَشَآءَ","wills"],["ٱللَّهُ","Allah"],["وَلَـٰكِنَّ","But"],["أَكْثَرَهُمْ","most of them"],["يَجْهَلُونَ","(are) ignorant"]]],"901":["(Dan demikianlah Kami jadikan bagi tiap-tiap nabi itu musuh) sebagaimana Kami telah jadikan mereka sebagai musuh-musuhmu; kemudian pengertian musuh itu dijelaskan (yakni setan-setan) siluman-siluman (dari jenis manusia dan jin yang memberikan bisikan) yang menghembuskan godaan (antara yang sebagian kepada sebagian lainnya tentang perkataan-perkataan yang indah-indah) yang memulas warna kebatilan (untuk membujuk) umat manusia. (Jika Tuhanmu menghendaki, niscaya mereka tidak mengerjakannya) maksudnya bisikan-bisikan yang menyesatkan tadi (maka tinggalkanlah mereka) biarkanlah orang-orang kafir itu (dan apa yang mereka ada-adakan) berupa kekafiran dan lain-lainnya yang sudah menjadi watak mereka; ayat ini diturunkan sebelum turunnya ayat perintah untuk berperang.",[["وَكَذَٰلِكَ","And thus"],["جَعَلْنَا","We made"],["لِكُلِّ","for every"],["نَبِىٍّ","Prophet"],["عَدُوًّۭا","an enemy "],["شَيَـٰطِينَ","devils"],["ٱلْإِنسِ","(from) the mankind"],["وَٱلْجِنِّ","and the jinn"],["يُوحِى","inspiring"],["بَعْضُهُمْ","some of them"],["إِلَىٰ","to"],["بَعْضٍۢ","others"],["زُخْرُفَ","(with) decorative"],["ٱلْقَوْلِ","[the] speech"],["غُرُورًۭا ۚ","(in) deception"],["وَلَوْ","But if"],["شَآءَ","(had) willed"],["رَبُّكَ","your Lord"],["مَا","not"],["فَعَلُوهُ ۖ","they (would) have done it"],["فَذَرْهُمْ","so leave them"],["وَمَا","and what"],["يَفْتَرُونَ","they invent"]]],"902":["(Dan juga agar mau mendengar) diathafkan kepada Lafal ghuruuran; artinya agar mau cenderung (kepada bisikan itu) yakni godaan tersebut (hati kecil) hati sanubari (orang-orang yang tidak beriman kepada kehidupan akhirat dan agar mereka merasa senang kepadanya dan supaya mereka mau mengerjakan) (apa yang setan-setan itu kerjakan) yaitu berupa perbuatan-perbuatan dosa sehingga mereka mendapat siksaan karenanya.",[["وَلِتَصْغَىٰٓ","And so that incline"],["إِلَيْهِ","to it"],["أَفْـِٔدَةُ","hearts"],["ٱلَّذِينَ","(of) those who"],["لَا","(do) not"],["يُؤْمِنُونَ","believe"],["بِٱلْـَٔاخِرَةِ","in the Hereafter"],["وَلِيَرْضَوْهُ","and so that they may be pleased with it"],["وَلِيَقْتَرِفُوا۟","and so that they may commit"],["مَا","what"],["هُم","they"],["مُّقْتَرِفُونَ","(are) committing"]]],"903":["Ayat ini diturunkan tatkala mereka meminta kepada Nabi saw. agar menjadikan seorang hakim yang melerai antara dia dan mereka; katakanlah: (Maka patutkah aku meminta kepada selain Allah) aku mencari (sebagai hakim) yang melerai antara aku dan kamu (padahal Dialah yang telah menurunkan Alkitab kepadamu) yakni Alquran (dengan terinci) di dalamnya terkandung penjelasan yang memisahkan antara perkara yang hak dengan perkara yang batil. (Orang-orang yang telah Kami datangkan kitab kepada mereka) yaitu kitab Taurat seperti Abdullah bin Salam dan teman-temannya (mereka mengetahui bahwa Alquran itu diturunkan) dengan dibaca takhfif dan dibaca tasydid (dari Tuhanmu dengan sebenarnya. Maka janganlah kamu sekali-kali termasuk orang-orang yang ragu-ragu) sehingga menjadi orang-orang yang bimbang terhadap Alquran. Yang dimaksud dengan pernyataan ini adalah sebagai bukti kepada orang-orang kafir bahwa sesungguhnya Alquran itu adalah benar.",[["أَفَغَيْرَ","Then is (it) other than"],["ٱللَّهِ","Allah"],["أَبْتَغِى","I seek"],["حَكَمًۭا","(as) judge"],["وَهُوَ","while He"],["ٱلَّذِىٓ","(is) the One Who"],["أَنزَلَ","has revealed"],["إِلَيْكُمُ","to you"],["ٱلْكِتَـٰبَ","the Book"],["مُفَصَّلًۭا ۚ","explained in detail"],["وَٱلَّذِينَ","And those (to) whom"],["ءَاتَيْنَـٰهُمُ","We gave them"],["ٱلْكِتَـٰبَ","the Book"],["يَعْلَمُونَ","they know"],["أَنَّهُۥ","that it"],["مُنَزَّلٌۭ","(is) sent down"],["مِّن","from"],["رَّبِّكَ","your Lord"],["بِٱلْحَقِّ ۖ","in truth"],["فَلَا","so (do) not"],["تَكُونَنَّ","be"],["مِنَ","among"],["ٱلْمُمْتَرِينَ","the ones who doubt"]]],"904":["(Dan telah sempurnalah kalimat Tuhanmu) yakni Alquran yang memuat hukum-hukum dan ancaman-ancaman (sebagai kalimat yang benar dan adil) menjadi tamyiz. (Tidak ada yang dapat mengubah-ubah kalimat-kalimat-Nya) baik dengan menguranginya atau menggantinya (dan Dialah Maha Mendengar) terhadap apa yang dikatakan olehnya (lagi Maha Mengetahui) tentang apa yang diperbuatnya.",[["وَتَمَّتْ","And (has been) fulfilled"],["كَلِمَتُ","(the) word"],["رَبِّكَ","(of) your Lord"],["صِدْقًۭا","(in) truth"],["وَعَدْلًۭا ۚ","and justice"],["لَّا","No"],["مُبَدِّلَ","one can change"],["لِكَلِمَـٰتِهِۦ ۚ","His words"],["وَهُوَ","and He"],["ٱلسَّمِيعُ","(is) the All-Hearer"],["ٱلْعَلِيمُ","the All-Knower"]]],"905":["(Dan jika kamu menuruti kebanyakan orang-orang yang di muka bumi) yakni orang-orang kafir (niscaya mereka akan menyesatkanmu dari jalan Allah) yaitu agama-Nya (sama sekali) (mereka tidak akan mau mengikuti kecuali hanya pada prasangka belaka) dalam perdebatan mereka denganmu tentang masalah bangkai, yaitu di kala mereka berkata, \"Apa yang telah dibunuh oleh Allah lebih berhak untuk kamu makan daripada apa yang kamu bunuh sendiri.\" (dan sama sekali) tidak lain (mereka hanyalah berdusta) di dalam hal tersebut.",[["وَإِن","And if"],["تُطِعْ","you obey"],["أَكْثَرَ","most"],["مَن","of"],["فِى","(those) in"],["ٱلْأَرْضِ","the earth"],["يُضِلُّوكَ","they will mislead you"],["عَن","from"],["سَبِيلِ","(the) way"],["ٱللَّهِ ۚ","(of) Allah"],["إِن","Not"],["يَتَّبِعُونَ","they follow"],["إِلَّا","except"],["ٱلظَّنَّ","[the] assumption"],["وَإِنْ","and not"],["هُمْ","they (do)"],["إِلَّا","except"],["يَخْرُصُونَ","guess"]]],"906":["(Sesungguhnya Tuhanmu Dialah yang lebih mengetahui) Maha Mengetahui (tentang orang yang tersesat dari jalan-Nya dan Dia lebih mengetahui tentang orang-orang yang mendapat petunjuk) dengan demikian maka Dia memberikan balasan pahala kepada mereka masing-masing.",[["إِنَّ","Indeed"],["رَبَّكَ","your Lord"],["هُوَ","He"],["أَعْلَمُ","knows best"],["مَن","who"],["يَضِلُّ","strays"],["عَن","from"],["سَبِيلِهِۦ ۖ","His way"],["وَهُوَ","and He"],["أَعْلَمُ","(is) most knowing"],["بِٱلْمُهْتَدِينَ","of the guided-ones"]]],"907":["(Maka makanlah binatang-binatang yang halal yang disebutkan nama Allah atasnya) yang disembelih dengan menyebut nama-Nya (jika kamu beriman kepada ayat-ayat-Nya.)",[["فَكُلُوا۟","So eat"],["مِمَّا","of what"],["ذُكِرَ","(is) mentioned"],["ٱسْمُ","(the) name"],["ٱللَّهِ","(of) Allah"],["عَلَيْهِ","on it"],["إِن","if"],["كُنتُم","you are"],["بِـَٔايَـٰتِهِۦ","in His Verses "],["مُؤْمِنِينَ","believers"]]],"908":["(Mengapa kamu tidak mau memakan binatang-binatang yang halal yang disebut nama Allah atasnya) yaitu hewan-hewan sembelihan (padahal sesungguhnya Allah telah menjelaskan) boleh juga dibaca dengan bina maf`ul atau bina fa`il untuk kedua fi`ilnya (kepada kamu apa yang diharamkan-Nya atasmu) yang telah disebutkan di dalam ayat, \"Telah diharamkan atas kamu bangkai...\" (Q.S. Al-Maidah 3) (kecuali apa yang terpaksa kamu harus memakannya) di antara apa yang diharamkan itu maka hal itu juga dihalalkan bagi kamu. Adapun maknanya ialah: tidak ada larangan bagi kamu untuk memakan apa-apa yang telah disebutkan itu; Allah telah menjelaskan kepadamu apa-apa yang diharamkan kamu memakannya, maka ini bukanlah termasuk yang itu. (Dan sesungguhnya kebanyakan dari manusia benar-benar hendak menyesatkan orang lain) dengan dibaca fatah atau damah huruf ya-nya (dengan hawa nafsu mereka) dengan apa yang disukai hawa nafsu mereka; di antaranya ialah menghalalkan bangkai dan lain-lainnya (tanpa pengetahuan) yang secara sengaja mereka melakukannya. (Sesungguhnya Tuhanmu Dialah yang lebih mengetahui orang-orang yang melampaui batas) artinya orang-orang yang melampaui batas perkara yang dihalalkan untuk melakukan hal-hal yang diharamkan.",[["وَمَا","And what"],["لَكُمْ","for you"],["أَلَّا","that not"],["تَأْكُلُوا۟","you eat"],["مِمَّا","of what"],["ذُكِرَ","has been mentioned"],["ٱسْمُ","(the) name"],["ٱللَّهِ","(of) Allah"],["عَلَيْهِ","on it"],["وَقَدْ","when indeed"],["فَصَّلَ","He (has) explained in detail"],["لَكُم","to you"],["مَّا","what"],["حَرَّمَ","He (has) forbidden"],["عَلَيْكُمْ","to you"],["إِلَّا","except"],["مَا","what"],["ٱضْطُرِرْتُمْ","you are compelled"],["إِلَيْهِ ۗ","to it"],["وَإِنَّ","And indeed"],["كَثِيرًۭا","many"],["لَّيُضِلُّونَ","surely lead astray"],["بِأَهْوَآئِهِم","by their (vain) desires"],["بِغَيْرِ","without"],["عِلْمٍ ۗ","knowledge"],["إِنَّ","Indeed"],["رَبَّكَ","your Lord"],["هُوَ","He"],["أَعْلَمُ","(is) most knowing"],["بِٱلْمُعْتَدِينَ","of the transgressors"]]],"909":["(Dan tinggalkanlah) berhentilah kamu dari melakukan (dosa yang tampak dan yang tersembunyi) maksudnya dosa yang terang-terangan dan dosa yang tersembunyi; dikatakan bahwa yang dimaksud adalah perbuatan zina; dan dikatakan lagi adalah semua perbuatan maksiat. (Sesungguhnya orang-orang yang mengerjakan dosa, kelak akan diberi pembalasan) pada hari kiamat (disebabkan apa yang telah mereka kerjakan) usahakan.",[["وَذَرُوا۟","Forsake"],["ظَـٰهِرَ","open"],["ٱلْإِثْمِ","[the] sins"],["وَبَاطِنَهُۥٓ ۚ","and the secret"],["إِنَّ","Indeed"],["ٱلَّذِينَ","those who"],["يَكْسِبُونَ","earn"],["ٱلْإِثْمَ","[the] sin"],["سَيُجْزَوْنَ","they will be recompensed"],["بِمَا","for what"],["كَانُوا۟","they used to"],["يَقْتَرِفُونَ","commit"]]],"910":["(Dan janganlah kamu memakan binatang-binatang yang tidak disebut nama Allah) seumpamanya karena mati dengan sendirinya atau disembelih dengan menyebut asma selain-Nya terkecuali apa yang disembelih oleh orang muslim, sekali pun tidak menyebut nama-Nya sewaktu menyembelihnya baik secara sengaja atau pun karena lupa, maka sembelihannya tetap halal, demikianlah menurut pendapat Ibnu Abbas, yang kemudian dianut oleh Imam Syafii. (Sesungguhnya) memakan hewan-hewan yang diharamkan itu (adalah suatu kefasikan) keluar dari garis apa yang telah dihalalkan. (Sesungguhnya setan itu membisikkan) menghembuskan godaannya (kepada kawan-kawannya) yaitu kepada orang-orang kafir (agar mereka membantah kamu) di dalam masalah menghalalkan bangkai (dan jika kamu menuruti mereka) di dalam hal ini (sesungguhnya kamu tentulah menjadi orang-orang musyrik). Ayat berikut ini diturunkan berkenaan dengan Abu Jahal dan lain-lainnya.",[["وَلَا","And (do) not"],["تَأْكُلُوا۟","eat"],["مِمَّا","of that"],["لَمْ","not"],["يُذْكَرِ","has been mentioned"],["ٱسْمُ","(the) name"],["ٱللَّهِ","(of) Allah"],["عَلَيْهِ","on it"],["وَإِنَّهُۥ","and indeed, it (is)"],["لَفِسْقٌۭ ۗ","grave disobedience"],["وَإِنَّ","And indeed"],["ٱلشَّيَـٰطِينَ","the devils"],["لَيُوحُونَ","inspire"],["إِلَىٰٓ","to"],["أَوْلِيَآئِهِمْ","their friends"],["لِيُجَـٰدِلُوكُمْ ۖ","so that they dispute with you"],["وَإِنْ","and if"],["أَطَعْتُمُوهُمْ","you obey them"],["إِنَّكُمْ","indeed, you"],["لَمُشْرِكُونَ","(would) be the polytheists"]]],"911":["(Dan apakah yang sudah mati) oleh sebab kekafirannya (kemudian dia Kami hidupkan) dengan hidayah (dan Kami berikan kepadanya cahaya yang terang yang dengan cahaya itu dia dapat berjalan di tengah-tengah masyarakat manusia) dia dapat pula melihat perkara yang benar berkat cahaya itu dan dapat membedakannya daripada yang lainnya; yang dimaksud adalah keimanan (serupa dengan orang yang keadaannya) Lafal mitsl adalah tambahan, yakni sebagaimana seseorang (yang keadaannya dalam gelap-gulita yang sekali-kali tidak dapat keluar darinya) dimaksud orang kafir; sebagai jawabannya ialah tentu saja tidak. (Demikianlah) sebagaimana orang-orang mukmin dihiasi dengan keimanan (orang-orang kafir pun dihiasi pula dengan apa yang telah mereka kerjakan) berupa kekafiran dan maksiat-maksiat.",[["أَوَمَن","Is (one) who"],["كَانَ","was"],["مَيْتًۭا","dead"],["فَأَحْيَيْنَـٰهُ","and We gave him life"],["وَجَعَلْنَا","and We made"],["لَهُۥ","for him"],["نُورًۭا","light"],["يَمْشِى","he walks"],["بِهِۦ","whereby"],["فِى","among"],["ٱلنَّاسِ","the people"],["كَمَن","like (one) who"],["مَّثَلُهُۥ","[similar to him]"],["فِى","(is) in"],["ٱلظُّلُمَـٰتِ","the darknesses"],["لَيْسَ","not"],["بِخَارِجٍۢ","he comes out"],["مِّنْهَا ۚ","of it"],["كَذَٰلِكَ","Thus"],["زُيِّنَ","is made fair-seeming"],["لِلْكَـٰفِرِينَ","to the disbelievers"],["مَا","what"],["كَانُوا۟","they were"],["يَعْمَلُونَ","doing"]]],"912":["(Dan demikianlah) sebagaimana yang telah Kami jadikan orang-orang fasik penduduk Mekah terdiri dari para pembesarnya (Kami adakan pada tiap-tiap negeri penjahat-penjahat yang terbesar agar mereka melakukan tipu daya dalam negeri itu) dengan cara menghalang-halangi jalan keimanan (Dan mereka tidak memperdayakan melainkan dirinya sendiri) sebab akibat perbuatannya menimpa diri mereka sendiri (sedangkan mereka tidak menyadarinya) tentang hal tersebut.",[["وَكَذَٰلِكَ","And thus"],["جَعَلْنَا","We placed"],["فِى","in"],["كُلِّ","every"],["قَرْيَةٍ","city"],["أَكَـٰبِرَ","greatest"],["مُجْرِمِيهَا","(of) its criminals"],["لِيَمْكُرُوا۟","so that they plot"],["فِيهَا ۖ","therein"],["وَمَا","And not"],["يَمْكُرُونَ","they plot"],["إِلَّا","except"],["بِأَنفُسِهِمْ","against themselves"],["وَمَا","and not"],["يَشْعُرُونَ","they perceive"]]],"913":["(Dan apabila datang kepada mereka) kepada penduduk Mekah (satu ayat) yang membenarkan Nabi saw. (mereka berkata, \"Kami tidak akan beriman) kepadanya (sehingga diberikan kepada kami yang serupa dengan apa yang telah diberikan kepada utusan-utusan Allah.\") berupa risalah dan wahyu kepada kami sebab kami adalah yang terbanyak hartanya dan yang paling tua umurnya lalu Allah swt. berfirman: (Allah lebih mengetahui di mana Dia menempatkan tugas kerasulan-Nya) dengan dibaca jamak dan tunggal dan Lafal haitsu menjadi maf`ul bihi dari fi`il yang ditunjuk oleh Lafal a`lamu. Artinya Allah mengetahui tempat yang layak untuk meletakkan risalah-Nya lalu Ia meletakkannya. Sedangkan mereka itu bukanlah orang-orang yang pantas untuk mengemban tugas risalah ini (orang-orang yang berdosa nanti akan ditimpa) sebab perkataan mereka itu (suatu kehinaan) yakni menjadi rendah (di sisi Allah dan siksa yang keras disebabkan mereka lalu membuat tipu daya) oleh tipu daya mereka sendiri.",[["وَإِذَا","And when"],["جَآءَتْهُمْ","comes to them"],["ءَايَةٌۭ","a Sign"],["قَالُوا۟","they say"],["لَن","Never"],["نُّؤْمِنَ","we will believe"],["حَتَّىٰ","until"],["نُؤْتَىٰ","we are given"],["مِثْلَ","like"],["مَآ","what"],["أُوتِىَ","was given"],["رُسُلُ","(to the) Messengers"],["ٱللَّهِ ۘ","(of) Allah"],["ٱللَّهُ","Allah"],["أَعْلَمُ","knows best"],["حَيْثُ","where"],["يَجْعَلُ","He places"],["رِسَالَتَهُۥ ۗ","His Message"],["سَيُصِيبُ","Will afflict"],["ٱلَّذِينَ","those who"],["أَجْرَمُوا۟","committed crimes"],["صَغَارٌ","a humiliation"],["عِندَ","from"],["ٱللَّهِ","Allah"],["وَعَذَابٌۭ","and a punishment"],["شَدِيدٌۢ","severe"],["بِمَا","for what"],["كَانُوا۟","they used to"],["يَمْكُرُونَ","plot"]]],"914":["(Siapa yang Allah menghendaki akan memberikan kepadanya petunjuk niscaya Dia melapangkan dadanya untuk memeluk agama Islam) dengan cara menyinarkan nur hidayah ke dalam dadanya sehingga dengan sadar ia mau menerima Islam dan mau membuka dadanya lebar-lebar untuk menerimanya. Demikianlah sebagaimana yang telah disebutkan dalam suatu hadis. (Dan siapa yang dikehendaki) Allah (kesesatannya niscaya Allah menjadikan dadanya sesak) dengan dibaca takhfif dan tasydid yakni merasa sempit untuk menerimanya (lagi sempit) terasa amat sempit; dengan dibaca kasrah huruf ra-nya menjadi sifat dan dibaca fathah sebagai mashdar yang diberi sifat dengan makna mubalaghah (seolah-olah ia sedang mendaki) menurut suatu qiraat dibaca yashsha`adu di dalam kedua bacaan tersebut berarti mengidgamkan ta asal ke dalam huruf shad. Menurut qiraat lainnya dengan dibaca sukun huruf shad-nya (ke langit) apabila iman dipaksakan kepadanya karena hal itu terasa berat sekali baginya. (Begitulah) sebagaimana kejadian itu (Allah menimpakan siksa) yakni azab atau setan, dengan pengertian azab atau setan itu menguasainya (kepada orang-orang yang tidak beriman).",[["فَمَن","So whoever"],["يُرِدِ","wants"],["ٱللَّهُ","Allah"],["أَن","that"],["يَهْدِيَهُۥ","He guides him "],["يَشْرَحْ","He expands"],["صَدْرَهُۥ","his breast"],["لِلْإِسْلَـٰمِ ۖ","to Islam"],["وَمَن","and whoever"],["يُرِدْ","He wants"],["أَن","that"],["يُضِلَّهُۥ","He lets him go astray"],["يَجْعَلْ","He makes"],["صَدْرَهُۥ","his breast"],["ضَيِّقًا","tight"],["حَرَجًۭا","and constricted"],["كَأَنَّمَا","as though"],["يَصَّعَّدُ","he (were) climbing"],["فِى","into"],["ٱلسَّمَآءِ ۚ","the sky"],["كَذَٰلِكَ","Thus"],["يَجْعَلُ","places"],["ٱللَّهُ","Allah"],["ٱلرِّجْسَ","the filth"],["عَلَى","on"],["ٱلَّذِينَ","those who"],["لَا","(do) not"],["يُؤْمِنُونَ","believe"]]],"915":["(Dan inilah) apa yang engkau berada di dalamnya hai Muhammad! (jalan) titian (Tuhanmu yang lurus) tidak ada liku-likunya; Lafal mustaqiiman dibaca nashab menjadi hal yang mengukuhkan jumlah, sedangkan yang menjadi `amilnya adalah makna isyarah. (Sesungguhnya Kami telah menjelaskan) Kami telah menerangkan (ayat-ayat Kami kepada orang-orang yang mengambil pelajaran) Lafal yadzdzakkaruun dengan mengidgamkan huruf ta tambahan ke dalam huruf dzal asal; maknanya orang-orang yang mau mengambil sebagai pelajaran. Mereka disebutkan secara khusus sebab merekalah orang-orang yang mengambil manfaat darinya.",[["وَهَـٰذَا","And this"],["صِرَٰطُ","(is the) way"],["رَبِّكَ","(of) your Lord "],["مُسْتَقِيمًۭا ۗ","straight"],["قَدْ","Certainly"],["فَصَّلْنَا","We have detailed"],["ٱلْـَٔايَـٰتِ","the Verses"],["لِقَوْمٍۢ","for a people"],["يَذَّكَّرُونَ","who take heed"]]],"916":["(Bagi mereka disediakan Darussalam) yakni rumah keselamatan atau surga (pada sisi Tuhannya dan Dialah Pelindung mereka disebabkan amal-amal saleh yang selalu mereka kerjakan).",[["۞ لَهُمْ","For them"],["دَارُ","(will be) home"],["ٱلسَّلَـٰمِ","(of) [the] peace"],["عِندَ","with"],["رَبِّهِمْ ۖ","their Lord"],["وَهُوَ","And He"],["وَلِيُّهُم","(will be) their protecting friend"],["بِمَا","because"],["كَانُوا۟","(of what) they used to"],["يَعْمَلُونَ","do"]]],"917":["(Dan) ingatlah (hari di waktu Kami menghimpun mereka semuanya) dengan memakai nun dan ya; artinya Allahlah yang menghimpun semua makhluk kemudian diserukan kepada mereka (\"Hai golongan jin/setan! Sesungguhnya kamu telah banyak menyesatkan manusia,\") dengan cara kamu menyesatkan mereka (lalu berkatalah kawan-kawan mereka) yaitu mereka yang mau menaatinya (dari kalangan manusia, \"Ya Tuhan kami, sesungguhnya sebagian daripada kami telah dapat kesenangan dari sebagian yang lainnya) manusia telah mengambil manfaat melalui jin yang menghiasi keinginan-keinginan nafsu syahwat mereka, dan demikian pula jin pun mengambil manfaat dari manusia melalui ketaatan manusia kepada mereka (dan kami telah sampai kepada waktu yang telah Engkau tentukan bagi kami\") yakni hari kiamat; hal ini adalah merupakan ungkapan kekecewaan mereka (Allah berfirman) Maha Tinggi Allah, kepada mereka melalui lisan para malaikat-Nya (\"Neraka itulah tempat kamu) tempat diam kamu (sedangkan kamu kekal di dalamnya, kecuali kalau Allah menghendaki yang lain.\") batas-batas waktu tertentu di mana mereka dapat dikeluarkan dari neraka, untuk meminum hamim/keringat ahli neraka yang berada di luar neraka, demikianlah seperti apa yang dikatakan dalam firman-Nya, \"Kemudian sesungguhnya tempat kembali mereka benar-benar ke neraka Jahim,\" surah Ash-Shaffaat. Dan telah diriwayatkan dari Ibnu Abbas bahwasanya ayat ini diturunkan berkenaan dengan orang-orang yang telah diketahui Allah bahwa mereka orang-orang yang beriman. Dengan demikian berarti Lafal maa bermakna man. (Sesungguhnya Tuhanmu Maha Bijaksana) di dalam mengatur ciptaan-Nya (lagi Maha Mengetahui) tentang makhluk-makhluk-Nya.",[["وَيَوْمَ","And (the) Day"],["يَحْشُرُهُمْ","He will gather them"],["جَمِيعًۭا","all"],["يَـٰمَعْشَرَ","(and will say), \"O assembly"],["ٱلْجِنِّ","(of) [the] jinn"],["قَدِ","Certainly"],["ٱسْتَكْثَرْتُم","you have (misled) many"],["مِّنَ","of"],["ٱلْإِنسِ ۖ","the mankind"],["وَقَالَ","And will say"],["أَوْلِيَآؤُهُم","their friends"],["مِّنَ","among"],["ٱلْإِنسِ","the men"],["رَبَّنَا","Our Lord"],["ٱسْتَمْتَعَ","profited"],["بَعْضُنَا","some of us"],["بِبَعْضٍۢ","by others"],["وَبَلَغْنَآ","and we have reached"],["أَجَلَنَا","our term"],["ٱلَّذِىٓ","which"],["أَجَّلْتَ","You appointed"],["لَنَا ۚ","for us"],["قَالَ","He will say"],["ٱلنَّارُ","The Fire"],["مَثْوَىٰكُمْ","(is) your abode"],["خَـٰلِدِينَ","will abide forever"],["فِيهَآ","in it"],["إِلَّا","except"],["مَا","(for) what"],["شَآءَ","wills"],["ٱللَّهُ ۗ","Allah"],["إِنَّ","Indeed"],["رَبَّكَ","your Lord"],["حَكِيمٌ","(is) All-Wise"],["عَلِيمٌۭ","All-Knowing"]]],"918":["(Dan demikianlah) sebagaimana yang telah Kami berikan nikmat kepada orang-orang yang maksiat dari golongan manusia dan jin sebagian mereka melalui sebagian lainnya (Kami jadikan berteman) saling bantu-membantu (sebagian orang-orang yang lalim itu dengan sebagian lainnya) atas sebagian lainnya (disebabkan apa yang mereka usahakan) berupa perbuatan-perbuatan maksiat.",[["وَكَذَٰلِكَ","And thus"],["نُوَلِّى","We make friends"],["بَعْضَ","some (of)"],["ٱلظَّـٰلِمِينَ","the wrongdoers"],["بَعْضًۢا","(to) others"],["بِمَا","for what"],["كَانُوا۟","they used to"],["يَكْسِبُونَ","earn"]]],"919":["(Hai golongan jin dan manusia, apakah belum datang kepadamu rasul-rasul dari golongan kamu sendiri) kalangan kamu sendiri; artinya sebagian kamu yang percaya kepada manusia atau utusan-utusan jin yang sengaja Kami biarkan mereka mendengar ucapan-ucapan para rasul Kami kemudian mereka menyampaikannya kepada kaumnya (yang menceritakan kepada kamu tentang ayat-ayat-Ku dan memperingatkan kamu tentang pertemuanmu dengan hari ini? Mereka berkata, \"Kami menjadi saksi atas diri kami sendiri.\") bahwa sesungguhnya kami telah menerimanya. Allah swt. berfirman: (Kehidupan dunia telah menipu mereka) sehingga mereka tidak mau beriman (dan mereka menjadi saksi atas diri mereka sendiri bahwa mereka adalah orang-orang yang kafir.)",[["يَـٰمَعْشَرَ","O assembly"],["ٱلْجِنِّ","(of) [the] jinn"],["وَٱلْإِنسِ","and [the] men"],["أَلَمْ","Did (there) not"],["يَأْتِكُمْ","come to you"],["رُسُلٌۭ","Messengers"],["مِّنكُمْ","from (among) you"],["يَقُصُّونَ","relating"],["عَلَيْكُمْ","to you"],["ءَايَـٰتِى","My Verses"],["وَيُنذِرُونَكُمْ","and warning you"],["لِقَآءَ","(of the) meeting"],["يَوْمِكُمْ","(of) your day"],["هَـٰذَا ۚ","this"],["قَالُوا۟","They will say"],["شَهِدْنَا","We bear witness"],["عَلَىٰٓ","against"],["أَنفُسِنَا ۖ","ourselves"],["وَغَرَّتْهُمُ","And deluded them"],["ٱلْحَيَوٰةُ","the life"],["ٱلدُّنْيَا","(of) the world"],["وَشَهِدُوا۟","and they will bear witness"],["عَلَىٰٓ","against"],["أَنفُسِهِمْ","themselves"],["أَنَّهُمْ","that they"],["كَانُوا۟","were"],["كَـٰفِرِينَ","disbelievers"]]],"920":["(Yang demikian itu) dengan mengutus para utusan (supaya) huruf lam dimuqaddarahkan sedangkan an berasal dari anna yang ditakhfifkan; yaitu berasal dari liannahu (Tuhanmu tidak membinasakan kota-kota secara aniaya) sebagian dari kota-kota itu (sedangkan penduduknya dalam keadaan lengah) dan belum pernah diutus kepada mereka seorang rasul pun yang memberikan penjelasan kepada mereka.",[["ذَٰلِكَ","That (is because)"],["أَن","[that]"],["لَّمْ","not"],["يَكُن","is"],["رَّبُّكَ","your Lord"],["مُهْلِكَ","one who destroys"],["ٱلْقُرَىٰ","the cities"],["بِظُلْمٍۢ","for (their) wrongdoing"],["وَأَهْلُهَا","while their people"],["غَـٰفِلُونَ","(are) unaware"]]],"921":["(Dan masing-masing) dari kalangan orang-orang itu (memperoleh derajat-derajat) pembalasan (sesuai dengan apa yang telah dikerjakannya) berupa pembalasan yang baik dan pembalasan yang buruk (Dan Tuhanmu tidak lengah dari apa yang mereka kerjakan) dengan memakai ya dan ta.",[["وَلِكُلٍّۢ","And for all"],["دَرَجَـٰتٌۭ","(will be) degrees"],["مِّمَّا","for what"],["عَمِلُوا۟ ۚ","they did"],["وَمَا","And not"],["رَبُّكَ","(is) your Lord"],["بِغَـٰفِلٍ","unaware"],["عَمَّا","about what"],["يَعْمَلُونَ","they do"]]],"922":["(Dan Tuhanmu Maha Kaya) tidak membutuhkan makhluk-Nya dan juga tidak membutuhkan ibadah mereka (lagi mempunyai rahmat. Jika Dia menghendaki niscaya Dia memusnahkan kamu) hai penduduk Mekah yakni membinasakan kalian (dan menggantimu dengan siapa yang dikehendaki-Nya setelah kamu musnah) di antara makhluk-Nya (sebagaimana Dia telah menjadikan kamu dari keturunan orang-orang lain) yang telah Dia memusnahkan akan tetapi Dia tetap membiarkan kamu sebagai rahmat atas kamu sekalian.",[["وَرَبُّكَ","And your Lord"],["ٱلْغَنِىُّ","(is) the Self-Sufficient"],["ذُو","(the) Possessor"],["ٱلرَّحْمَةِ ۚ","(of) mercy"],["إِن","If"],["يَشَأْ","He wills"],["يُذْهِبْكُمْ","He can take you away"],["وَيَسْتَخْلِفْ","and grant succession"],["مِنۢ","from"],["بَعْدِكُم","after you"],["مَّا","(to) whom"],["يَشَآءُ","He wills"],["كَمَآ","as"],["أَنشَأَكُم","He raised you"],["مِّن","from"],["ذُرِّيَّةِ","the descendants"],["قَوْمٍ","(of) people"],["ءَاخَرِينَ","other"]]],"923":["(Sesungguhnya apa yang dijanjikan kepadamu) pada hari kiamat dan azab (pasti datang) tidak dapat ditawar-tawar lagi (dan kamu sekali-kali tidak sanggup menolaknya) tidak bisa selamat dari azab Kami.",[["إِنَّ","Indeed"],["مَا","what"],["تُوعَدُونَ","you are promised"],["لَـَٔاتٍۢ ۖ","(is) sure to come"],["وَمَآ","And not"],["أَنتُم","(can) you"],["بِمُعْجِزِينَ","escape (it)"]]],"924":["(Katakanlah) kepada mereka (\"Hai kaumku! Berbuatlah sepenuh kemampuanmu) sesuai dengan keadaanmu (sesungguhnya aku pun berbuat pula) sesuai dengan keadaanku. (Kelak kamu akan mengetahui siapakah di antara kita) man menjadi maushul dan menjadi maf`ul dari Lafal al-`ilm (yang akan memperoleh hasil yang baik dari dunia ini.\") akibat yang dipuji di akhirat nanti, apakah kami atau kamu? (Sesungguhnya tidak akan mendapat keberuntungan) kebahagiaan (orang-orang yang lalim itu) yaitu orang-orang kafir.",[["قُلْ","Say"],["يَـٰقَوْمِ","O my people"],["ٱعْمَلُوا۟","Work"],["عَلَىٰ","on"],["مَكَانَتِكُمْ","your position"],["إِنِّى","Indeed, I am"],["عَامِلٌۭ ۖ","a worker"],["فَسَوْفَ","And soon"],["تَعْلَمُونَ","you will know"],["مَن","who"],["تَكُونُ","will have"],["لَهُۥ","for himself"],["عَـٰقِبَةُ","(in) the end"],["ٱلدَّارِ ۗ","(a good) home"],["إِنَّهُۥ","Indeed [he]"],["لَا","(will) not"],["يُفْلِحُ","succeed"],["ٱلظَّـٰلِمُونَ","the wrongdoers"]]],"925":["(Dan mereka memperuntukkan) orang-orang kafir Mekah (bagi Allah satu bagian dari apa yang telah diciptakan)-Nya (yaitu berupa tanaman) hasil lahan (dan ternak sebagai bagian) yang mereka infakkan untuk tamu-tamu dan orang-orang miskin dan juga satu bagian lainnya untuk sesembahan-sesembahan mereka yang mereka berikan kepada para juru kuncinya (lalu mereka berkata sesuai dengan prasangka mereka, \"Ini untuk Allah) dengan dibaca fatah dan damah huruf zai-nya (dan ini untuk berhala-berhala kami.\") maksudnya apabila ada sesuatu yang terjatuh dari bagian untuk sesembahan mereka, mereka berani mengambilnya kembali. Tetapi apabila ada sesuatu yang terjatuh, dari bagian untuk Allah mereka membiarkannya kemudian mereka berkata, \"Sesungguhnya Allah tidak membutuhkan ini.\" Demikianlah sebagaimana yang diungkapkan dalam firman-Nya berikut ini: (Maka sajian-sajian yang diperuntukkan bagi berhala-berhala mereka tidak sampai kepada Allah) (dan sajian-sajian yang diperuntukkan bagi Allah, maka sajian itu sampai kepada berhala-berhala mereka. Amat buruklah) amat jeleklah (apa yang mereka tetapkan) yakni keputusan hukum mereka itu.",[["وَجَعَلُوا۟","And they assign"],["لِلَّهِ","to Allah"],["مِمَّا","out of what"],["ذَرَأَ","He produced"],["مِنَ","of"],["ٱلْحَرْثِ","the crops"],["وَٱلْأَنْعَـٰمِ","and the cattle"],["نَصِيبًۭا","a share"],["فَقَالُوا۟","and they say"],["هَـٰذَا","This"],["لِلَّهِ","(is) for Allah"],["بِزَعْمِهِمْ","by their claim"],["وَهَـٰذَا","And this"],["لِشُرَكَآئِنَا ۖ","(is) for our partners"],["فَمَا","But what"],["كَانَ","is"],["لِشُرَكَآئِهِمْ","for their partners"],["فَلَا","(does) not"],["يَصِلُ","reach"],["إِلَى","[to]"],["ٱللَّهِ ۖ","Allah"],["وَمَا","while what"],["كَانَ","is"],["لِلَّهِ","for Allah"],["فَهُوَ","then it"],["يَصِلُ","reaches"],["إِلَىٰ","[to]"],["شُرَكَآئِهِمْ ۗ","their partners"],["سَآءَ","Evil"],["مَا","(is) what"],["يَحْكُمُونَ","they judge"]]],"926":["(Dan demikianlah) sebagaimana telah menjadi kebiasaan mereka apa-apa yang telah disebutkan itu (telah menghiasi kebanyakan orang-orang musyrik memandang baik membunuh anak-anak mereka) dengan cara mengubur mereka hidup-hidup (karena hasutan sesembahan-sesembahan mereka) yang terdiri dari makhluk jin. Dengan dibaca rafa' sebagai fa'il dari fi'il zayyana; dan menurut suatu qiraat dengan dibaca bina maf'ul serta Lafal qatla dibaca rafa', dan dibaca nashab Lafal al-awlaad, berdasarkan bacaan ini Lafal syurakaaihim dibaca jar dengan mengidhafatkannya kepada Lafal al-qatlu; dengan demikian berarti ada fashal/pemisah antara mudhaf dan mudhaf ilaih yang dipisahkan oleh maf'ul, hal ini tidak mengapa, sebab mengidhafatkan Lafal al-qatlu kepada Lafal syurakaa karena merekalah pada hakikatnya yang melakukannya melalui bujukan mereka (untuk membinasakan mereka) untuk memusnahkan mereka (dan untuk mengaburkan) dengan mencampur-adukkan (bagi mereka agamanya. Dan kalau Allah menghendaki niscaya mereka tidak mengerjakannya, maka tinggalkanlah mereka dan apa yang mereka ada-adakan).",[["وَكَذَٰلِكَ","And likewise"],["زَيَّنَ","made pleasing"],["لِكَثِيرٍۢ","to many"],["مِّنَ","of"],["ٱلْمُشْرِكِينَ","the polytheists "],["قَتْلَ","(the) killing"],["أَوْلَـٰدِهِمْ","(of) their children "],["شُرَكَآؤُهُمْ","their partners "],["لِيُرْدُوهُمْ","so that they may ruin them"],["وَلِيَلْبِسُوا۟","and that they make confusing"],["عَلَيْهِمْ","to them"],["دِينَهُمْ ۖ","their religion"],["وَلَوْ","And if"],["شَآءَ","(had) willed"],["ٱللَّهُ","Allah"],["مَا","not"],["فَعَلُوهُ ۖ","(would) they have done so"],["فَذَرْهُمْ","So leave them"],["وَمَا","and what"],["يَفْتَرُونَ","they invent"]]],"927":["(Dan mereka mengatakan, \"Inilah binatang ternak dan tanaman yang dilarang) yang diharamkan (tidak boleh memakannya kecuali orang yang kami kehendaki\") yaitu para pelayan berhala-berhala dan lain-lainnya (menurut anggapan mereka) artinya mereka tidak punya alasan lagi dalam masalah ini (dan ada binatang ternak yang diharamkan menungganginya) maka ternak-ternak itu tidak boleh dinaiki, seperti hewan sawaib dan hewan hawami (dan binatang ternak yang mereka tidak menyebut nama Allah atasnya) di kala menyembelihnya melainkan menyebut nama berhala-berhala mereka kemudian mengaitkan hal itu kepada Allah (semata-mata membuat-buat kedustaan terhadap Allah. Kelak Allah akan membalas mereka terhadap apa yang selalu mereka ada-adakan) sebagai balasannya.",[["وَقَالُوا۟","And they say"],["هَـٰذِهِۦٓ","These"],["أَنْعَـٰمٌۭ","(are) cattle"],["وَحَرْثٌ","and crops"],["حِجْرٌۭ","forbidden"],["لَّا","no (one)"],["يَطْعَمُهَآ","can eat them"],["إِلَّا","except"],["مَن","whom"],["نَّشَآءُ","we will"],["بِزَعْمِهِمْ","by their claim"],["وَأَنْعَـٰمٌ","And cattle"],["حُرِّمَتْ","forbidden"],["ظُهُورُهَا","(are) their backs"],["وَأَنْعَـٰمٌۭ","and cattle"],["لَّا","not"],["يَذْكُرُونَ","they mention"],["ٱسْمَ","(the) name"],["ٱللَّهِ","(of) Allah"],["عَلَيْهَا","on it"],["ٱفْتِرَآءً","(as) an invention"],["عَلَيْهِ ۚ","against Him"],["سَيَجْزِيهِم","He will recompense them"],["بِمَا","for what"],["كَانُوا۟","they used to"],["يَفْتَرُونَ","invent"]]],"928":["(Dan mereka mengatakan, \"Apa yang dalam perut binatang ini) yaitu ternak yang diharamkan untuk dimakan seperti ternak sawaib dan ternak bahair (adalah khusus) dihalalkan (untuk pria kami dan diharamkan atas wanita kami\") yakni haram untuk perempuan-perempuan kami (dan jika yang dalam perut itu dilahirkan mati) dengan dibaca rafa` dan nashab serta fi`il dita`nitskan atau ditadzkirkan (maka pria dan wanita sama-sama boleh memakannya. Kelak akan membalas mereka) yakni Allah (terhadap ketetapan mereka) berupa pembelaan azab atas penghalalan dan pengharaman ini (Sesungguhnya Allah Maha Bijaksana) dalam ciptaan-Nya (lagi Maha Mengetahui) tentang makhluk-Nya.",[["وَقَالُوا۟","And they say"],["مَا","What"],["فِى","(is) in"],["بُطُونِ","(the) wombs"],["هَـٰذِهِ","(of) these"],["ٱلْأَنْعَـٰمِ","cattle"],["خَالِصَةٌۭ","(is) exclusively"],["لِّذُكُورِنَا","for our males"],["وَمُحَرَّمٌ","and forbidden"],["عَلَىٰٓ","on"],["أَزْوَٰجِنَا ۖ","our spouses"],["وَإِن","But if"],["يَكُن","is"],["مَّيْتَةًۭ","(born) dead"],["فَهُمْ","then they (all)"],["فِيهِ","in it"],["شُرَكَآءُ ۚ","(are) partners"],["سَيَجْزِيهِمْ","He will recompense them"],["وَصْفَهُمْ ۚ","(for) their attribution"],["إِنَّهُۥ","Indeed, He"],["حَكِيمٌ","(is) All-Wise"],["عَلِيمٌۭ","All-Knowing"]]],"929":["(Sesungguhnya rugilah orang-orang yang membunuh) dengan dibaca takhfif dan tasydid (anak-anak mereka) dengan mengubur mereka hidup-hidup (karena kebodohan) karena ketidakmengertian mereka (lagi tidak mengetahui dan mereka mengharamkan apa yang Allah telah memberi rezeki kepada mereka) yaitu apa-apa yang telah disebutkan (dengan semata-mata mengada-adakan terhadap Allah. Sesungguhnya mereka telah sesat dan tidaklah mereka mendapat petunjuk.)",[["قَدْ","Certainly"],["خَسِرَ","(are) lost"],["ٱلَّذِينَ","those who"],["قَتَلُوٓا۟","killed"],["أَوْلَـٰدَهُمْ","their children"],["سَفَهًۢا","(in) foolishness"],["بِغَيْرِ","without"],["عِلْمٍۢ","knowledge"],["وَحَرَّمُوا۟","and forbid"],["مَا","what"],["رَزَقَهُمُ","(bas been) provided (to) them"],["ٱللَّهُ","(by) Allah "],["ٱفْتِرَآءً","inventing (lies)"],["عَلَى","against"],["ٱللَّهِ ۚ","Allah"],["قَدْ","Certainly"],["ضَلُّوا۟","they have gone astray"],["وَمَا","and not"],["كَانُوا۟","they are"],["مُهْتَدِينَ","guided-ones"]]],"930":["(Dan Dialah yang menjadikan) yang telah menciptakan (kebun-kebun) yang mendatar di permukaan tanah, seperti tanaman semangka (dan yang tidak terhampar) yang berdiri tegak di atas pohon seperti pohon kurma (dan) Dia menjadikan (pohon kurma dan tanaman-tanaman yang bermacam-macam buahnya) yakni yang berbeda-beda buah dan bijinya baik bentuk maupun rasanya (dan zaitun dan delima yang serupa) dedaunannya; menjadi hal (dan tidak sama) rasa keduanya (Makanlah dari buahnya yang bermacam-macam itu bila dia berbuah) sebelum masak betul (dan tunaikanlah haknya di hari memetik hasilnya) dengan dibaca fatah atau kasrah; yaitu sepersepuluhnya atau setengahnya (dan janganlah kamu berlebih-lebihan) dengan memberikannya semua tanpa sisa sedikit pun buat orang-orang tanggunganmu. (Sesungguhnya Allah tidak menyukai orang-orang yang berlebih-lebihan) yaitu orang-orang yang melampaui batas hal-hal yang telah ditentukan bagi mereka.",[["۞ وَهُوَ","And He"],["ٱلَّذِىٓ","(is) the One Who"],["أَنشَأَ","produced"],["جَنَّـٰتٍۢ","gardens"],["مَّعْرُوشَـٰتٍۢ","trellised"],["وَغَيْرَ","and other than"],["مَعْرُوشَـٰتٍۢ","trellised"],["وَٱلنَّخْلَ","and the date-palm"],["وَٱلزَّرْعَ","and the crops"],["مُخْتَلِفًا","diverse"],["أُكُلُهُۥ","(are) its taste"],["وَٱلزَّيْتُونَ","and the olives"],["وَٱلرُّمَّانَ","and the pomegranates"],["مُتَشَـٰبِهًۭا","similar"],["وَغَيْرَ","and other than"],["مُتَشَـٰبِهٍۢ ۚ","similar"],["كُلُوا۟","Eat"],["مِن","of"],["ثَمَرِهِۦٓ","its fruit"],["إِذَآ","when"],["أَثْمَرَ","it bears fruit"],["وَءَاتُوا۟","and give"],["حَقَّهُۥ","its due"],["يَوْمَ","(on the) day"],["حَصَادِهِۦ ۖ","(of) its harvest"],["وَلَا","And (do) not"],["تُسْرِفُوٓا۟ ۚ","(be) extravagant"],["إِنَّهُۥ","Indeed, He"],["لَا","(does) not"],["يُحِبُّ","love"],["ٱلْمُسْرِفِينَ","the ones who are extravagant"]]],"931":["(Dan) Dia menjadikan (di antara binatang ternak itu sebagai kendaraan angkutan) yaitu layak untuk mengangkut barang-barang, seperti unta yang sudah dewasa (dan sebagai binatang sembelihan) yang tak layak untuk dijadikan angkutan, seperti unta yang masih muda dan kambing. Ia dinamakan farsy/hamparan karena ia mirip dengan hamparan tanah mengingat ia sangat dekat dengannya. (Makanlah dari rezeki yang telah diberikan Allah kepadamu dan janganlah kamu mengikuti langkah-langkah setan) jalan setan di dalam masalah pengharaman dan penghalalan. (Sesungguhnya setan itu musuh yang nyata bagimu) yang jelas permusuhannya.",[["وَمِنَ","And of"],["ٱلْأَنْعَـٰمِ","the cattle"],["حَمُولَةًۭ","(are some for) burden"],["وَفَرْشًۭا ۚ","and (some for) meat"],["كُلُوا۟","Eat"],["مِمَّا","of what"],["رَزَقَكُمُ","(has been) provided (to) you"],["ٱللَّهُ","(by) Allah"],["وَلَا","and (do) not"],["تَتَّبِعُوا۟","follow"],["خُطُوَٰتِ","(the) footsteps"],["ٱلشَّيْطَـٰنِ ۚ","(of) Shaitaan"],["إِنَّهُۥ","Indeed, he"],["لَكُمْ","(is) to you"],["عَدُوٌّۭ","an enemy"],["مُّبِينٌۭ","open"]]],"932":["(Yaitu delapan binatang yang berpasangan) yang bermacam-macam, menjadi badal dari Lafal humuulah dan farasy (dari domba) yang sejodoh (sepasang) jantan dan betina (dan dari kambing) dibaca fathah atau sukun (sepasang. Katakanlah) hai Muhammad, terhadap orang yang terkadang mengharamkan binatang jantan dan terkadang mengharamkan binatang betina kemudian ia mengaitkan hal itu kepada Allah (\"Apakah dua yang jantan) baik dari kambing maupun dari domba (diharamkan) Allah atas kamu (ataukah dua yang betina) dari kedua jenis ternak itu (ataukah yang ada dalam kandungan dua betinanya?\") baik jantan atau pun betina. (Terangkanlah kepadaku dengan berdasar pengetahuan) tentang cara pengharaman hal itu (jika kamu memang orang-orang yang benar) di dalam ayat ini terkandung makna sebagai berikut: dari manakah datangnya pengharaman itu? Apabila dari pihak jantan, maka semua binatang yang jantan berarti haram; atau bila dari pihak betina, maka berarti semua binatang betina haram hukumnya dan demikian pula binatang-binatang yang masih berada di dalam rahimnya maka berarti kedua jenis itu diharamkan. Lalu dari manakah adanya pengecualian ini sedangkan kata tanya menunjukkan makna ingkar.",[["ثَمَـٰنِيَةَ","Eight"],["أَزْوَٰجٍۢ ۖ","pairs "],["مِّنَ","of"],["ٱلضَّأْنِ","the sheep"],["ٱثْنَيْنِ","two"],["وَمِنَ","and of"],["ٱلْمَعْزِ","the goats"],["ٱثْنَيْنِ ۗ","two"],["قُلْ","Say"],["ءَآلذَّكَرَيْنِ","(Are) the two males"],["حَرَّمَ","He has forbidden"],["أَمِ","or"],["ٱلْأُنثَيَيْنِ","the two females"],["أَمَّا","or what"],["ٱشْتَمَلَتْ","contains"],["عَلَيْهِ","[in it]"],["أَرْحَامُ","(the) wombs"],["ٱلْأُنثَيَيْنِ ۖ","(of) the two females"],["نَبِّـُٔونِى","Inform me"],["بِعِلْمٍ","with knowledge"],["إِن","if"],["كُنتُمْ","you are"],["صَـٰدِقِينَ","truthful"]]],"933":["(Dan dari sepasang unta dan dari sepasang lembu, katakanlah, \"Apakah dua yang jantan yang diharamkan ataukah dua yang betina, ataukah yang ada di dalam kandungan dua betinanya. Apakah) bahkan (kamu menyaksikan) hadir (di waktu Allah menetapkan ini bagimu?) tentang pengharaman ini kemudian sengaja kamu menyatakan hal ini, tidak, bahkan kamu adalah orang-orang yang dusta dalam hal ini. (Maka siapakah) tak ada seorang pun (yang lebih lalim daripada orang-orang yang membuat-buat dusta terhadap Allah) dalam hal itu (untuk menyesatkan manusia tanpa pengetahuan?\" Sesungguhnya Allah tidak memberi petunjuk kepada orang-orang yang lalim.)",[["وَمِنَ","And of"],["ٱلْإِبِلِ","the camels"],["ٱثْنَيْنِ","two"],["وَمِنَ","and of"],["ٱلْبَقَرِ","the cows"],["ٱثْنَيْنِ ۗ","two"],["قُلْ","Say"],["ءَآلذَّكَرَيْنِ","(Is it) the two males"],["حَرَّمَ","He (has) forbidden"],["أَمِ","or"],["ٱلْأُنثَيَيْنِ","the two females"],["أَمَّا","or what"],["ٱشْتَمَلَتْ","contains"],["عَلَيْهِ","[in it]"],["أَرْحَامُ","(the) wombs"],["ٱلْأُنثَيَيْنِ ۖ","(of) the two females"],["أَمْ","Or"],["كُنتُمْ","were you"],["شُهَدَآءَ","witnesses"],["إِذْ","when"],["وَصَّىٰكُمُ","enjoined you"],["ٱللَّهُ","Allah"],["بِهَـٰذَا ۚ","with this"],["فَمَنْ","Then who"],["أَظْلَمُ","(is) more unjust"],["مِمَّنِ","than (one) who"],["ٱفْتَرَىٰ","invents"],["عَلَى","against"],["ٱللَّهِ","Allah"],["كَذِبًۭا","a lie"],["لِّيُضِلَّ","to mislead"],["ٱلنَّاسَ","the people"],["بِغَيْرِ","without"],["عِلْمٍ ۗ","knowledge"],["إِنَّ","Indeed"],["ٱللَّهَ","Allah"],["لَا","(does) not"],["يَهْدِى","guide"],["ٱلْقَوْمَ","the people"],["ٱلظَّـٰلِمِينَ","the wrongdoing"]]],"934":["(Katakanlah, \"Tiadalah aku peroleh dalam wahyu yang diwahyukan kepadaku) tentang sesuatu (yang diharamkan bagi orang yang hendak memakannya kecuali kalau yang dimakan itu) dengan memakai ya dan ta (bangkai) dengan dibaca nashab dan menurut suatu qiraat dibaca rafa` serta tahtaniyyah (atau darah yang mengalir) yang beredar berbeda dengan darah yang tidak mengalir seperti hati dan limpa (atau daging babi karena sesungguhnya semua itu kotor) haram (atau) kecuali jika hewan itu (binatang yang disembelih atas nama selain Allah) yakni hewan yang dipotong dengan menyebut nama selain nama Allah. (Siapa yang dalam keadaan terpaksa) menghadapi semua yang telah disebutkan sehingga ia memakannya (sedangkan ia tidak menginginkannya dan tidak pula melampaui batas, maka sesungguhnya Tuhanmu Maha Pengampun) kepadanya atas apa yang telah dimakannya (lagi Maha Penyayang.\") terhadapnya. Kemudian apa yang telah disebutkan itu dilengkapi dengan sebuah hadis yang menambahkan yaitu setiap hewan yang bertaring dan setiap burung yang berkuku tajam.",[["قُل","Say"],["لَّآ","Not"],["أَجِدُ","(do) I find"],["فِى","in"],["مَآ","what"],["أُوحِىَ","has been revealed"],["إِلَىَّ","to me"],["مُحَرَّمًا","(anything) forbidden"],["عَلَىٰ","to"],["طَاعِمٍۢ","an eater"],["يَطْعَمُهُۥٓ","who eats it"],["إِلَّآ","except"],["أَن","that"],["يَكُونَ","it be"],["مَيْتَةً","dead"],["أَوْ","or"],["دَمًۭا","blood"],["مَّسْفُوحًا","poured forth"],["أَوْ","or"],["لَحْمَ","(the) flesh"],["خِنزِيرٍۢ","(of) swine "],["فَإِنَّهُۥ","for indeed, it"],["رِجْسٌ","(is) filth "],["أَوْ","or"],["فِسْقًا","(it be) disobedience"],["أُهِلَّ","[is] dedicated"],["لِغَيْرِ","to other than"],["ٱللَّهِ","Allah"],["بِهِۦ ۚ","[on it]"],["فَمَنِ","But whoever"],["ٱضْطُرَّ","(is) compelled"],["غَيْرَ","not"],["بَاغٍۢ","desiring"],["وَلَا","and not"],["عَادٍۢ","transgressing"],["فَإِنَّ","then indeed"],["رَبَّكَ","your Lord"],["غَفُورٌۭ","(is) Oft-Forgiving"],["رَّحِيمٌۭ","Most Merciful"]]],"935":["(Dan kepada orang-orang Yahudi) yaitu pemeluk agama Yahudi (Kami haramkan segala binatang yang berkuku) maksudnya hewan yang jari-jari kakinya tidak terpisah-pisah seperti unta dan burung unta (dan dari sapi dan domba, Kami haramkan atas mereka lemak dari kedua binatang) yaitu lemak perut dan lemak pantat (kecuali lemak yang melekat di punggung keduanya) lemak yang menggantung pada punggungnya (atau) yang menempel (di perut besar) yang ada di lambung, kata jamak dari haawiyaa atau haawiyah (atau yang bercampur dengan tulang) lemak yang menempel di tulang, maka jenis lemak ini dihalalkan untuk mereka. (Demikianlah) masalah pengharaman ini (Kami hukum mereka) sebagai balasan (atas kedurhakaan mereka) oleh sebab kelaliman mereka sendiri sebagaimana yang telah disebutkan dalam surah An-Nisa (dan sesungguhnya Kami adalah Maha Benar) di dalam berita-berita Kami dan janji-janji Kami.",[["وَعَلَى","And to"],["ٱلَّذِينَ","those who"],["هَادُوا۟","are Jews"],["حَرَّمْنَا","We forbade"],["كُلَّ","every"],["ذِى","(animal) with"],["ظُفُرٍۢ ۖ","claws"],["وَمِنَ","and of"],["ٱلْبَقَرِ","the cows"],["وَٱلْغَنَمِ","and the sheep"],["حَرَّمْنَا","We forbade"],["عَلَيْهِمْ","to them"],["شُحُومَهُمَآ","their fat"],["إِلَّا","except"],["مَا","what"],["حَمَلَتْ","carried"],["ظُهُورُهُمَآ","their backs"],["أَوِ","or"],["ٱلْحَوَايَآ","the entrails"],["أَوْ","or"],["مَا","what"],["ٱخْتَلَطَ","(is) joined"],["بِعَظْمٍۢ ۚ","with the bone"],["ذَٰلِكَ","That"],["جَزَيْنَـٰهُم","(is) their recompense"],["بِبَغْيِهِمْ ۖ","for their rebellion"],["وَإِنَّا","And indeed, We"],["لَصَـٰدِقُونَ","[surely] are truthful"]]],"936":["(Maka jika mereka mendustakan kamu) mengenai apa yang engkau sampaikan (katakanlah,) kepada mereka (\"Tuhanmu mempunyai rahmat yang luas) sehingga Dia tidak menyegerakan untuk menghukum kamu; di dalam ayat ini terkandung ajakan yang lembut untuk mereka kepada keimanan (dan siksa-Nya tidak dapat ditolak) yakni azab-Nya apabila datang (dari kaum yang berdosa.\")",[["فَإِن","But if"],["كَذَّبُوكَ","they deny you"],["فَقُل","then say"],["رَّبُّكُمْ","Your Lord"],["ذُو","(is the) Possessor"],["رَحْمَةٍۢ","(of) Mercy"],["وَٰسِعَةٍۢ","Vast"],["وَلَا","but not"],["يُرَدُّ","will be turned back"],["بَأْسُهُۥ","His wrath"],["عَنِ","from"],["ٱلْقَوْمِ","the people"],["ٱلْمُجْرِمِينَ","(who are) criminals"]]],"937":["(0rang-orang yang mempersekutukan Tuhan akan mengatakan, \"Jika Allah menghendaki niscaya kami tidak mempersekutukan-Nya) (dan juga bapak-bapak kami dan tidak pula kami mengharamkan sesuatu apa pun.\") kemusyrikan kami dan pengharaman kami adalah berdasarkan kehendak-Nya, Dia rela dengan ketentuan itu. Allah berfirman: (Demikian pulalah) sebagaimana mereka telah mendustakan (orang-orang yang sebelum mereka telah mendustakan) para utusan mereka (sampai mereka merasakan siksaan Kami) azab Kami (Katakanlah, \"Adakah kamu mempunyai sesuatu pengetahuan) bahwa Allah telah rela dengan hal itu (sehingga dapat kamu mengemukakannya kepada Kami?\") pasti kamu tidak mempunyai pengetahuan tentang hal ini. (Tidak) tiadakan (kamu mengikuti) dalam hal ini (kecuali hanya dugaan belaka dan tidak lain) tiada lain (kamu hanya berdusta) hanya membual.",[["سَيَقُولُ","Will say"],["ٱلَّذِينَ","those who"],["أَشْرَكُوا۟","associate partners (with Allah)"],["لَوْ","If"],["شَآءَ","Had willed"],["ٱللَّهُ","Allah"],["مَآ","not"],["أَشْرَكْنَا","we (would) have associated partners (with Allah)"],["وَلَآ","and not"],["ءَابَآؤُنَا","our forefathers"],["وَلَا","and not"],["حَرَّمْنَا","we (would) have forbidden"],["مِن","[of]"],["شَىْءٍۢ ۚ","anything"],["كَذَٰلِكَ","Likewise"],["كَذَّبَ","denied"],["ٱلَّذِينَ","those who"],["مِن","(were from)"],["قَبْلِهِمْ","before them"],["حَتَّىٰ","until"],["ذَاقُوا۟","they tasted"],["بَأْسَنَا ۗ","Our wrath"],["قُلْ","Say"],["هَلْ","Is"],["عِندَكُم","with you"],["مِّنْ","[of]"],["عِلْمٍۢ","any knowledge"],["فَتُخْرِجُوهُ","then produce it"],["لَنَآ ۖ","for us"],["إِن","Not"],["تَتَّبِعُونَ","you follow"],["إِلَّا","except"],["ٱلظَّنَّ","the assumption"],["وَإِنْ","and not"],["أَنتُمْ","you (do)"],["إِلَّا","but"],["تَخْرُصُونَ","guess"]]],"938":["(Katakanlah) apabila kamu tidak mempunyai hujah (\"Allah mempunyai hujah yang jelas lagi kuat) yang sempurna (maka jika Dia menghendaki) memberikan hidayah kepadamu (pasti Dia memberi hidayah kepada kamu semuanya.\")",[["قُلْ","Say"],["فَلِلَّهِ","With Allah"],["ٱلْحُجَّةُ","(is) the argument "],["ٱلْبَـٰلِغَةُ ۖ","the conclusive"],["فَلَوْ","And if"],["شَآءَ","He (had) willed"],["لَهَدَىٰكُمْ","surely He (would) have guided you"],["أَجْمَعِينَ","all"]]],"939":["(Katakanlah, \"Bawalah ke mari) datangkanlah (saksi-saksi kamu yang dapat mempersaksikan bahwasanya Allah telah mengharamkan ini\") yaitu makanan yang kamu haramkan. (Jika mereka mempersaksikan, maka janganlah kamu ikut pula menjadi saksi bersama mereka dan janganlah kamu mengikuti hawa nafsu orang-orang yang mendustakan ayat-ayat Kami dan orang-orang yang tidak beriman kepada kehidupan akhirat sedangkan mereka mempersekutukan Tuhan mereka) berlaku musyrik terhadap-Nya.",[["قُلْ","Say"],["هَلُمَّ","Bring forward"],["شُهَدَآءَكُمُ","your witnesses"],["ٱلَّذِينَ","those who"],["يَشْهَدُونَ","testify"],["أَنَّ","that"],["ٱللَّهَ","Allah"],["حَرَّمَ","prohibited"],["هَـٰذَا ۖ","this"],["فَإِن","Then if"],["شَهِدُوا۟","they testify"],["فَلَا","then (do) not"],["تَشْهَدْ","testify"],["مَعَهُمْ ۚ","with them"],["وَلَا","And (do) not"],["تَتَّبِعْ","follow"],["أَهْوَآءَ","(the) desires"],["ٱلَّذِينَ","(of) those who"],["كَذَّبُوا۟","denied"],["بِـَٔايَـٰتِنَا","Our Signs"],["وَٱلَّذِينَ","and those who"],["لَا","(do) not"],["يُؤْمِنُونَ","believe"],["بِٱلْـَٔاخِرَةِ","in the Hereafter"],["وَهُم","while they"],["بِرَبِّهِمْ","with their Lord"],["يَعْدِلُونَ","set up equals"]]],"940":["(Katakanlah, \"Marilah kubacakan yang diharamkan atas kamu oleh Tuhanmu, yaitu) an bermakna menafsirkan (janganlah kamu mempersekutukan sesuatu dengan Dia dan) berbuat baiklah (terhadap kedua orang tua sebaik-baiknya dan janganlah kamu membunuh anak-anak kamu) dengan menguburkan hidup-hidup (karena) sebab (takut kemiskinan) kemelaratan yang kamu khawatirkan (Kami akan memberi rezeki kepadamu dan kepada mereka dan janganlah kamu mendekati perbuatan-perbuatan yang keji) dosa-dosa besar seperti perbuatan zina (baik yang tampak di antaranya maupun yang tersembunyi) yang kelihatan dan yang tidak kelihatan. (Dan janganlah kamu membunuh jiwa yang diharamkan Allah membunuhnya kecuali dengan sesuatu sebab yang benar.\") yaitu seperti hukum kisas dan hudud murtad serta rajam bagi yang pezina muhshan. (Demikian itu) apa yang telah disebutkan itu (adalah yang diperintahkan oleh Tuhanmu kepadamu supaya kamu memahaminya) supaya kamu memikirkannya.",[["۞ قُلْ","Say"],["تَعَالَوْا۟","Come"],["أَتْلُ","I will recite"],["مَا","what"],["حَرَّمَ","has prohibited"],["رَبُّكُمْ","your Lord"],["عَلَيْكُمْ ۖ","to you"],["أَلَّا","That (do) not"],["تُشْرِكُوا۟","associate"],["بِهِۦ","with Him"],["شَيْـًۭٔا ۖ","anything"],["وَبِٱلْوَٰلِدَيْنِ","and with the parents"],["إِحْسَـٰنًۭا ۖ","(be) good"],["وَلَا","and (do) not"],["تَقْتُلُوٓا۟","kill"],["أَوْلَـٰدَكُم","your children"],["مِّنْ","(out) of"],["إِمْلَـٰقٍۢ ۖ","poverty"],["نَّحْنُ","We"],["نَرْزُقُكُمْ","provide for you"],["وَإِيَّاهُمْ ۖ","and for them"],["وَلَا","And (do) not"],["تَقْرَبُوا۟","go near"],["ٱلْفَوَٰحِشَ","[the] immoralities"],["مَا","what"],["ظَهَرَ","(is) apparent"],["مِنْهَا","of them"],["وَمَا","and what"],["بَطَنَ ۖ","(is) concealed"],["وَلَا","And (do) not"],["تَقْتُلُوا۟","kill"],["ٱلنَّفْسَ","the soul"],["ٱلَّتِى","which"],["حَرَّمَ","has (been) forbidden"],["ٱللَّهُ","(by) Allah"],["إِلَّا","except"],["بِٱلْحَقِّ ۚ","by (legal) right"],["ذَٰلِكُمْ","That"],["وَصَّىٰكُم","(He) has enjoined on you"],["بِهِۦ","with it"],["لَعَلَّكُمْ","so that you may"],["تَعْقِلُونَ","use reason"]]],"941":["(Dan janganlah kamu dekati harta anak yatim kecuali dengan cara) dengan sikap yang (lebih baik) yaitu cara yang di dalamnya mengandung kemaslahatan/manfaat bagi anak yatim hingga ia dewasa) seumpamanya dia sudah balig. (Dan sempurnakanlah takaran dan timbangan dengan adil) secara adil dan tidak curang. (Kami tidak memikulkan beban kepada seseorang melainkan sekadar kesanggupannya) sesuai dengan kemampuannya dalam hal ini; apabila ia berbuat kekeliruan di dalam menakar atau menimbang sesuatu, maka Allah mengetahui kebenaran niat yang sesungguhnya, oleh karena itu maka ia tidak berdosa, sebagaimana yang telah disebutkan dalam hadis Nabi saw. (Dan apabila kamu berkata) dalam masalah hukum atau lainnya (maka hendaklah kamu berlaku adil) jujur (kendatipun dia) orang yang bersangkutan (adalah kerabatmu) famili (dan penuhilah janji Allah. Yang demikian itu diperintahkan Allah kepadamu agar kamu ingat) dengan memakai tasydid agar menjadikannya sebagai pelajaran; dan juga dibaca dengan sukun.",[["وَلَا","And (do) not"],["تَقْرَبُوا۟","go near"],["مَالَ","wealth"],["ٱلْيَتِيمِ","(of) the orphans"],["إِلَّا","except"],["بِٱلَّتِى","with that"],["هِىَ","which"],["أَحْسَنُ","(is) best"],["حَتَّىٰ","until"],["يَبْلُغَ","he reaches"],["أَشُدَّهُۥ ۖ","his maturity"],["وَأَوْفُوا۟","And give full"],["ٱلْكَيْلَ","[the] measure"],["وَٱلْمِيزَانَ","and the weight"],["بِٱلْقِسْطِ ۖ","with justice"],["لَا","Not"],["نُكَلِّفُ","We burden"],["نَفْسًا","any soul"],["إِلَّا","except"],["وُسْعَهَا ۖ","(to) its capacity"],["وَإِذَا","And when"],["قُلْتُمْ","you speak"],["فَٱعْدِلُوا۟","then be just"],["وَلَوْ","even if"],["كَانَ","he is"],["ذَا","(one of)"],["قُرْبَىٰ ۖ","a near relative"],["وَبِعَهْدِ","And (the) Covenant"],["ٱللَّهِ","(of) Allah"],["أَوْفُوا۟ ۚ","fulfil"],["ذَٰلِكُمْ","That"],["وَصَّىٰكُم","(He) has enjoined on you"],["بِهِۦ","with it"],["لَعَلَّكُمْ","so that you may"],["تَذَكَّرُونَ","remember"]]],"942":["(Dan bahwa) dengan memakai harakat fatah mentakdirkan lam, dan dengan memakai harakat kasrah sebagai jumlah isti'naf/permulaan (hal ini) apa yang Kami pesankan kepada kamu (adalah jalan-Ku yang lurus) menjadi hal (maka ikutilah dia; dan janganlah kamu mengikuti jalan-jalan) cara-cara yang bertentangan dengannya (karena jalan itu mencerai-beraikan) dengan membuang salah satu di antara dua huruf ta, yakni akan menyelewengkan (kamu dari jalan-Nya) agama-Nya (yang demikian itu diperintahkan Allah kepadamu agar kamu bertakwa.)",[["وَأَنَّ","And that"],["هَـٰذَا","this"],["صِرَٰطِى","(is) My path"],["مُسْتَقِيمًۭا","straight"],["فَٱتَّبِعُوهُ ۖ","so follow it"],["وَلَا","And (do) not"],["تَتَّبِعُوا۟","follow"],["ٱلسُّبُلَ","the (other) paths"],["فَتَفَرَّقَ","then they will separate"],["بِكُمْ","you"],["عَن","from"],["سَبِيلِهِۦ ۚ","His path"],["ذَٰلِكُمْ","That"],["وَصَّىٰكُم","(He) has enjoined on you"],["بِهِۦ","[with it]"],["لَعَلَّكُمْ","so that you may"],["تَتَّقُونَ","become righteous"]]],"943":["(Kemudian Kami telah memberikan Alkitab kepada Musa) kitab Taurat; tsumma bermakna untuk tertibnya rentetan kisah (untuk menyempurnakan) nikmat (kepada orang-orang yang berbuat kebaikan) agar mengamalkan kandungan isinya (dan untuk menjelaskan) menerangkan (segala sesuatu) yang diperlukan dalam masalah agama (dan sebagai petunjuk dan rahmat agar mereka) kaum Bani Israel (terhadap hari pertemuan dengan Tuhan mereka) dengan dibangkitkannya mereka (mereka mau beriman.)",[["ثُمَّ","Moreover"],["ءَاتَيْنَا","We gave"],["مُوسَى","Musa"],["ٱلْكِتَـٰبَ","the Book"],["تَمَامًا","completing (Our Favor)"],["عَلَى","on"],["ٱلَّذِىٓ","the one who"],["أَحْسَنَ","did good"],["وَتَفْصِيلًۭا","and an explanation"],["لِّكُلِّ","of every"],["شَىْءٍۢ","thing"],["وَهُدًۭى","and a guidance"],["وَرَحْمَةًۭ","and mercy"],["لَّعَلَّهُم","so that they may"],["بِلِقَآءِ","in (the) meeting"],["رَبِّهِمْ","(with) their Lord"],["يُؤْمِنُونَ","believe"]]],"944":["(Dan ini) maksudnya Alquran ini (adalah kitab yang Kami turunkan yang diberkati, maka ikutilah dia) hai penduduk Mekah dengan mengamalkan apa yang dikandungnya (dan bertakwalah kamu) jangan melakukan kekafiran (agar kamu diberi rahmat) Kami turunkan dia yaitu Alquran.",[["وَهَـٰذَا","And this"],["كِتَـٰبٌ","(is) a Book"],["أَنزَلْنَـٰهُ","We have revealed it "],["مُبَارَكٌۭ","blessed"],["فَٱتَّبِعُوهُ","so follow it"],["وَٱتَّقُوا۟","and fear (Allah)"],["لَعَلَّكُمْ","so that you may"],["تُرْحَمُونَ","receive mercy"]]],"945":["(Agar jangan) tidak (kamu mengatakan bahwa kitab itu hanya diturunkan kepada dua golongan saja) yaitu golongan Yahudi dan golongan Nasrani (sebelum kami dan sesungguhnya) ditakhfifkan dari innaa yang bertasydid sedangkan isimnya dibuang (kami terhadap pelajaran mereka) apa yang mereka baca (tidak memperhatikan) oleh sebab kami tidak mengerti tentangnya karena bukan bahasa kami.",[["أَن","Lest"],["تَقُولُوٓا۟","you say"],["إِنَّمَآ","Only"],["أُنزِلَ","was revealed"],["ٱلْكِتَـٰبُ","the Book"],["عَلَىٰ","on"],["طَآئِفَتَيْنِ","the two groups"],["مِن","from"],["قَبْلِنَا","before us"],["وَإِن","and indeed"],["كُنَّا","we were"],["عَن","about"],["دِرَاسَتِهِمْ","their study"],["لَغَـٰفِلِينَ","certainly unaware"]]],"946":["(Atau agar kamu tidak mengatakan, \"Sesungguhnya jika kitab itu diturunkan kepada kami tentulah kami lebih mendapat petunjuk dari mereka.\") oleh karena kebersihan hati kami. (Sesungguhnya telah datang kepada kamu keterangan yang nyata) yaitu penjelasan (dari Tuhanmu, petunjuk dan rahmat) bagi orang yang mengikutinya (maka siapakah) artinya tidak ada seorang pun (yang lebih lalim daripada orang yang mendustakan ayat-ayat Allah dan berpaling) memalingkan diri (daripadanya. Kelak Kami akan memberi balasan kepada orang-orang yang berpaling dari ayat-ayat Kami dengan siksaan yang buruk) siksaan yang paling keras (disebabkan mereka selalu berpaling.)",[["أَوْ","Or"],["تَقُولُوا۟","you say"],["لَوْ","If"],["أَنَّآ","[that]"],["أُنزِلَ","was revealed"],["عَلَيْنَا","to us"],["ٱلْكِتَـٰبُ","the Book"],["لَكُنَّآ","surely we (would) have been"],["أَهْدَىٰ","better guided"],["مِنْهُمْ ۚ","than them"],["فَقَدْ","So verily"],["جَآءَكُم","has come to you"],["بَيِّنَةٌۭ","clear proofs"],["مِّن","from"],["رَّبِّكُمْ","your Lord"],["وَهُدًۭى","and a Guidance"],["وَرَحْمَةٌۭ ۚ","and a Mercy"],["فَمَنْ","Then who"],["أَظْلَمُ","(is) more unjust"],["مِمَّن","than (he) who"],["كَذَّبَ","denies"],["بِـَٔايَـٰتِ","[with] (the) Verses"],["ٱللَّهِ","(of) Allah"],["وَصَدَفَ","and turns away"],["عَنْهَا ۗ","from them"],["سَنَجْزِى","We will recompense"],["ٱلَّذِينَ","those who"],["يَصْدِفُونَ","turn away"],["عَنْ","from"],["ءَايَـٰتِنَا","Our Signs"],["سُوٓءَ","(with) an evil"],["ٱلْعَذَابِ","punishment"],["بِمَا","because"],["كَانُوا۟","they used to"],["يَصْدِفُونَ","turn away"]]],"947":["(Tiadalah yang mereka nantikan) apa yang mereka nanti-nanti (kecuali hanyalah datang kepada mereka) dapat dibaca ta`tiyahum atau ya`tiyahum (malaikat-malaikat) untuk mencabut arwah-arwah mereka (atau kedatangan Tuhanmu) yaitu perintah-Nya yang dimaksud adalah azab-Nya (atau kedatangan beberapa ayat Tuhanmu) tanda-tanda dari Tuhanmu yang menunjukkan dekatnya hari kiamat. (Pada hari datangnya beberapa ayat dari Tuhanmu) terbitnya matahari dari ufuk barat sebagaimana yang telah disebutkan di dalam hadis riwayat Bukhari dan Muslim (tidaklah bermanfaat lagi iman seseorang kepada dirinya sendiri yang belum beriman sebelum itu) jumlah lam takun menjadi sifat dari Lafal nafsan (atau) jiwa yang belum pernah (mengusahakan kebaikan dalam masa imannya) yakni ketaatan; artinya tobatnya tidak lagi bermanfaat bagi dirinya seperti apa yang telah dijelaskan oleh hadis. (Katakanlah, \"Tunggulah olehmu) salah satu dari alamat-alamat tersebut (sesungguhnya kami pun menunggu pula.\") hal tersebut.",[["هَلْ","Are"],["يَنظُرُونَ","they waiting"],["إِلَّآ","except"],["أَن","that"],["تَأْتِيَهُمُ","comes to them"],["ٱلْمَلَـٰٓئِكَةُ","the Angels"],["أَوْ","or"],["يَأْتِىَ","comes"],["رَبُّكَ","your Lord"],["أَوْ","or"],["يَأْتِىَ","comes"],["بَعْضُ","some (of)"],["ءَايَـٰتِ","(the) Signs"],["رَبِّكَ ۗ","(of) your Lord"],["يَوْمَ","(The) Day"],["يَأْتِى","(when) comes"],["بَعْضُ","some (of)"],["ءَايَـٰتِ","(the) Signs"],["رَبِّكَ","(of) your Lord"],["لَا","not"],["يَنفَعُ","will benefit"],["نَفْسًا","a soul"],["إِيمَـٰنُهَا","its faith"],["لَمْ","not"],["تَكُنْ","(if) it had"],["ءَامَنَتْ","believed"],["مِن","from"],["قَبْلُ","before"],["أَوْ","or"],["كَسَبَتْ","earned"],["فِىٓ","through"],["إِيمَـٰنِهَا","its faith"],["خَيْرًۭا ۗ","any good"],["قُلِ","Say"],["ٱنتَظِرُوٓا۟","Wait"],["إِنَّا","Indeed, we"],["مُنتَظِرُونَ","(are) those who wait"]]],"948":["(Sesungguhnya orang-orang yang memecah belah agamanya) oleh sebab mereka bercerai-berai di dalamnya, yaitu mereka mengambil sebagian peraturannya dan meninggalkan sebagian lainnya (dan mereka menjadi berpuak-puak) menjadi bersekte-sekte dan masalah agama. Menurut suatu qiraat artinya mereka berpecah-belah dan meninggalkan agamanya yang harus mereka peluk, mereka adalah orang-orang Yahudi dan Nasrani (tidak ada sedikit pun tanggung jawabmu terhadap mereka) janganlah engkau menghalang-halangi mereka. (Sesungguhnya urusan mereka hanyalah terserah kepada Allah) Dialah yang mengurusnya (kemudian Allah memberitahukan kepada mereka) di akhirat kelak (apa yang telah mereka perbuat) Allah memberikan balasan kepada mereka. Ayat ini telah dinasakh dengan turunnya ayat saif/ayat yang memerintahkan berperang.",[["إِنَّ","Indeed"],["ٱلَّذِينَ","those who"],["فَرَّقُوا۟","divide"],["دِينَهُمْ","their religion"],["وَكَانُوا۟","and become"],["شِيَعًۭا","sects"],["لَّسْتَ","you are not"],["مِنْهُمْ","with them"],["فِى","in"],["شَىْءٍ ۚ","anything"],["إِنَّمَآ","Only"],["أَمْرُهُمْ","their affair"],["إِلَى","(is) with"],["ٱللَّهِ","Allah"],["ثُمَّ","then"],["يُنَبِّئُهُم","He will inform them"],["بِمَا","of what"],["كَانُوا۟","they used to"],["يَفْعَلُونَ","do"]]],"949":["(Siapa membawa amal yang baik) yakni zikir laa ilaaha illallaah/tidak ada tuhan selain Allah (maka baginya pahala sepuluh kali lipat amalnya) balasan pahalanya adalah sepuluh kali kebaikan (dan siapa membawa perbuatan yang jahat, maka dia tidak diberi pembalasan melainkan seimbang dengan kejahatannya) balasannya yang setimpal (sedang mereka sedikit pun tidak dianiaya atau dirugikan) dikurangi sesuatu dari pembalasan yang sebenarnya.",[["مَن","Whoever"],["جَآءَ","came"],["بِٱلْحَسَنَةِ","with a good deed"],["فَلَهُۥ","then for him"],["عَشْرُ","(is) ten (times)"],["أَمْثَالِهَا ۖ","the like of it"],["وَمَن","And whoever"],["جَآءَ","came"],["بِٱلسَّيِّئَةِ","with an evil deed"],["فَلَا","then not"],["يُجْزَىٰٓ","he will be recompensed"],["إِلَّا","except"],["مِثْلَهَا","the like of it"],["وَهُمْ","and they"],["لَا","will not"],["يُظْلَمُونَ","(be) wronged"]]],"950":["(Katakanlah, \"Sesungguhnya Aku telah ditunjuki oleh Tuhanku kepada jalan yang lurus) kemudian dijadikan badal (yaitu agama yang benar) agama yang lurus (agama Ibrahim yang lurus dan Ibrahim itu bukanlah termasuk orang-orang yang musyrik\").",[["قُلْ","Say"],["إِنَّنِى","Indeed (as for) me"],["هَدَىٰنِى","has guided me"],["رَبِّىٓ","my Lord"],["إِلَىٰ","to"],["صِرَٰطٍۢ","a path"],["مُّسْتَقِيمٍۢ","straight "],["دِينًۭا","a religion"],["قِيَمًۭا","right"],["مِّلَّةَ","religion"],["إِبْرَٰهِيمَ","(of) Ibrahim "],["حَنِيفًۭا ۚ","a true monotheist"],["وَمَا","And not"],["كَانَ","he was"],["مِنَ","from"],["ٱلْمُشْرِكِينَ","the polytheists"]]],"951":["(Katakanlah, \"Sesungguhnya salatku, ibadahku) amal ibadahku, yaitu ibadah haji dan lain-lainnya (hidupku) kehidupanku (dan matiku) meninggalku (hanyalah untuk Allah, Tuhan semesta alam).",[["قُلْ","Say"],["إِنَّ","Indeed"],["صَلَاتِى","my prayer"],["وَنُسُكِى","and my rites of sacrifice"],["وَمَحْيَاىَ","and my living"],["وَمَمَاتِى","and my dying"],["لِلَّهِ","(are) for Allah"],["رَبِّ","Lord"],["ٱلْعَـٰلَمِينَ","(of) the worlds"]]],"952":["(Tiada sekutu bagi-Nya) di dalam hal tersebut (dan demikian itulah) ketauhidan (yang diperintahkan kepadaku, dan aku adalah orang yang pertama-tama menyerahkan diri kepada Allah\") dari kalangan umat ini.",[["لَا","No"],["شَرِيكَ","partners"],["لَهُۥ ۖ","for Him"],["وَبِذَٰلِكَ","and with that"],["أُمِرْتُ","I have been commanded"],["وَأَنَا۠","And I am"],["أَوَّلُ","(the) first"],["ٱلْمُسْلِمِينَ","(of) the ones who surrender (to Him)"]]],"953":["(Katakanlah, \"Apakah aku akan mencari Tuhan selain Allah) sebagai sesembahan; artinya aku tidak mencari Tuhan selain-Nya (Dia adalah Tuhan) yang memiliki (segala sesuatu. Dan tidaklah seorang membuat dosa) berbuat dosa (melainkan kemudaratannya kembali kepada dirinya sendiri; dan seorang yang berdosa tidak akan memikul) maksudnya seseorang tidak akan memikul (dosa) perbuatan dosa (orang lain. Kemudian kepada Tuhanmulah kamu kembali dan akan diberitakannya kepadamu apa yang kamu perselisihkan.)",[["قُلْ","Say"],["أَغَيْرَ","Is (it) other than"],["ٱللَّهِ","Allah"],["أَبْغِى","I (should) seek"],["رَبًّۭا","(as) a Lord"],["وَهُوَ","while He"],["رَبُّ","(is) the Lord"],["كُلِّ","(of) every"],["شَىْءٍۢ ۚ","thing"],["وَلَا","And not"],["تَكْسِبُ","earns"],["كُلُّ","every"],["نَفْسٍ","soul"],["إِلَّا","except"],["عَلَيْهَا ۚ","against itself"],["وَلَا","and not"],["تَزِرُ","bears"],["وَازِرَةٌۭ","any bearer of burden"],["وِزْرَ","burden"],["أُخْرَىٰ ۚ","(of) another"],["ثُمَّ","Then"],["إِلَىٰ","to"],["رَبِّكُم","your Lord"],["مَّرْجِعُكُمْ","(is) your return"],["فَيُنَبِّئُكُم","then He will inform you"],["بِمَا","about what"],["كُنتُمْ","you were"],["فِيهِ","concerning it"],["تَخْتَلِفُونَ","differing"]]],"954":["(Dan Dialah yang menjadikan kamu penguasa-penguasa di bumi) jamak dari kata khalifah; yakni sebagian di antara kamu mengganti sebagian lainnya di dalam masalah kekhalifahan ini (dan Dia meninggikan sebagian kamu atas sebagian yang lain beberapa derajat) dengan harta benda, kedudukan dan lain sebagainya (untuk mengujimu) untuk mencobamu (tentang apa yang diberikan kepadamu) artinya Dia memberi kamu agar jelas siapakah di antara kamu yang taat dan siapakah yang maksiat. (Sesungguhnya Tuhanmu itu adalah amat cepat siksaan-Nya) terhadap orang-orang yang berbuat maksiat kepada-Nya (dan sesungguhnya Dia Maha Pengampun) terhadap orang-orang mukmin (lagi Maha Penyayang.\") terhadap mereka.",[["وَهُوَ","And He"],["ٱلَّذِى","(is) the One Who"],["جَعَلَكُمْ","(has) made you"],["خَلَـٰٓئِفَ","successors"],["ٱلْأَرْضِ","(of) the earth"],["وَرَفَعَ","and raised"],["بَعْضَكُمْ","some of you"],["فَوْقَ","above"],["بَعْضٍۢ","others"],["دَرَجَـٰتٍۢ","(in) ranks"],["لِّيَبْلُوَكُمْ","so that He may test you"],["فِى","in"],["مَآ","what"],["ءَاتَىٰكُمْ ۗ","He has given you"],["إِنَّ","Indeed"],["رَبَّكَ","your Lord"],["سَرِيعُ","(is) swift"],["ٱلْعِقَابِ","(in) the punishment"],["وَإِنَّهُۥ","and indeed, He (is)"],["لَغَفُورٌۭ","[certainly], Oft-Forgiving"],["رَّحِيمٌۢ","Most Merciful"]]],"955":["(Alif laam miim shaad) hanya Allah-lah yang mengetahui apa yang dimaksud dengannya.",[["الٓمٓصٓ","Alif Laam Meem Saad"]]],"956":["Ini adalah (kitab yang diturunkan kepadamu) khithab atau pembicaraan ayat ini ditujukan kepada Nabi saw. (maka janganlah ada kesempitan di dalam dadamu) kerumitan (karenanya) sewaktu engkau akan menyampaikannya karena merasa khawatir akan didustakan (supaya kamu memberi peringatan) berkaitan dengan lafal unzila, artinya supaya engkau memperingatkan (dengan kitab itu dan menjadi pelajaran) yaitu bahan pengingat (bagi orang-orang yang beriman) kepada kitab itu.",[["كِتَـٰبٌ","(This is) a Book"],["أُنزِلَ","revealed"],["إِلَيْكَ","to you"],["فَلَا","so (let) not"],["يَكُن","be"],["فِى","in"],["صَدْرِكَ","your breast"],["حَرَجٌۭ","any uneasiness"],["مِّنْهُ","from it"],["لِتُنذِرَ","that you warn"],["بِهِۦ","with it"],["وَذِكْرَىٰ","and a reminder"],["لِلْمُؤْمِنِينَ","for the believers"]]],"957":["Katakanlah kepada mereka, (Ikutilah apa yang diturunkan kepadamu dari Tuhanmu) yakni Alquran (dan janganlah kamu mengikuti) maksudnya jangan kamu menjadikan (selain-Nya) selain Allah, (sebagai pemimpin-pemimpin) yang kamu taati untuk berbuat maksiat kepada Allah swt. (Amat sedikitlah kamu mengambil pelajaran) dengan memakai ta atau ya; yakni mengambil pelajaran darinya. Lafal tadzakkaruun dibaca dengan mengidgamkan ta asal ke dalam dzal. Menurut suatu qiraat dibaca tadzkuruun. Sedangkan huruf maa adalah tambahan, yang diadakan untuk mengukuhkan makna sedikit, sehingga artinya menjadi amat sedikit.",[["ٱتَّبِعُوا۟","Follow"],["مَآ","what"],["أُنزِلَ","has been revealed"],["إِلَيْكُم","to you"],["مِّن","from"],["رَّبِّكُمْ","your Lord"],["وَلَا","and (do) not"],["تَتَّبِعُوا۟","follow"],["مِن","from"],["دُونِهِۦٓ","beside Him"],["أَوْلِيَآءَ ۗ","any allies"],["قَلِيلًۭا","Little"],["مَّا","(is) what"],["تَذَكَّرُونَ","you remember"]]],"958":["(Betapa banyaknya) kalimat berita dan menjadi maf`ul (negeri) yang dimaksud adalah penduduknya (yang telah Kami binasakan) Kami bermaksud untuk membinasakannya (maka datanglah kekuatan Kami) yakni siksaan Kami (tengah malam) yaitu pada malam hari (atau di waktu mereka beristirahat di tengah hari) artinya sedang tidur-tiduran di siang hari. Yang dimaksud dengan al-qailulah, artinya beristirahat di tengah hari sekalipun tidak tidur. Yakni siksaan itu terkadang datang di waktu tengah malam dan terkadang di siang hari.",[["وَكَم","And how many"],["مِّن","of"],["قَرْيَةٍ","a city"],["أَهْلَكْنَـٰهَا","We destroyed it"],["فَجَآءَهَا","and came to it"],["بَأْسُنَا","Our punishment"],["بَيَـٰتًا","(at) night"],["أَوْ","or"],["هُمْ","(while) they"],["قَآئِلُونَ","were sleeping at noon"]]],"959":["(Maka tidak adalah keluhan mereka) yaitu perkataan mereka (di waktu datang kepada mereka siksaan Kami kecuali mengatakan, \"Sesungguhnya kami adalah orang-orang yang lalim.\")",[["فَمَا","Then not"],["كَانَ","was"],["دَعْوَىٰهُمْ","their plea"],["إِذْ","when"],["جَآءَهُم","came to them"],["بَأْسُنَآ","Our punishment"],["إِلَّآ","except"],["أَن","that"],["قَالُوٓا۟","they said"],["إِنَّا","Indeed, we"],["كُنَّا","were"],["ظَـٰلِمِينَ","wrongdoers"]]],"960":["(Maka sesungguhnya Kami akan menanyai umat-umat yang telah diutus rasul-rasul kepada mereka) yaitu kepada umat-umat tentang tanggapan mereka terhadap rasul-rasul dan pengamalan mereka terhadap apa-apa yang telah disampaikan kepada mereka (dan sesungguhnya Kami akan menanyai pula rasul-rasul Kami) tentang penyampaian mereka.",[["فَلَنَسْـَٔلَنَّ","Then surely We will question"],["ٱلَّذِينَ","those (to) whom"],["أُرْسِلَ","were sent"],["إِلَيْهِمْ","to them (Messengers)"],["وَلَنَسْـَٔلَنَّ","and surely We will question"],["ٱلْمُرْسَلِينَ","the Messengers"]]],"961":["(Maka sesungguhnya akan Kami kabarkan kepada mereka dengan penuh pengetahuan). Kami akan menceritakan kepada mereka tentang apa-apa yang telah mereka perbuat dengan penuh pengetahuan (dan Kami sekali-kali tidak gaib) untuk menyampaikan kepada rasul-rasul dan umat-umat terdahulu tentang apa-apa yang pernah mereka perbuat.",[["فَلَنَقُصَّنَّ","Then surely We will narrate"],["عَلَيْهِم","to them"],["بِعِلْمٍۢ ۖ","with knowledge"],["وَمَا","and not"],["كُنَّا","were We"],["غَآئِبِينَ","absent"]]],"962":["(Dan timbangan) untuk amal-amal perbuatan atau untuk lembaran-lembaran catatan amal perbuatan yang ditaruh di dalamnya. Timbangan itu memiliki jarum penunjuk berat dan dua gantungan, demikian sebagaimana yang telah dijelaskan oleh hadis. Timbangan itu ada (pada hari itu) yakni hari penghisaban yang telah disebutkan, yaitu hari kiamat (adalah benar) adalah adil, menjadi sifat dari lafal al-wazn (maka barang siapa berat timbangannya) oleh kebaikan (maka mereka itulah orang-orang yang berbahagia) orang-orang yang beruntung.",[["وَٱلْوَزْنُ","And the weighing"],["يَوْمَئِذٍ","that day"],["ٱلْحَقُّ ۚ","(will be) the truth"],["فَمَن","So whose "],["ثَقُلَتْ","(will be) heavy"],["مَوَٰزِينُهُۥ","his scales"],["فَأُو۟لَـٰٓئِكَ","then those"],["هُمُ","[they]"],["ٱلْمُفْلِحُونَ","(will be) the successful ones"]]],"963":["(Dan siapa yang ringan timbangannya) oleh sebab amal-amal keburukannya (maka itulah orang-orang yang merugikan dirinya sendiri) yang membawa dirinya ke neraka (disebabkan mereka selalu mengingkari ayat-ayat Kami) mereka tidak mau mempercayainya.",[["وَمَنْ","And (for) those"],["خَفَّتْ","(will be) light"],["مَوَٰزِينُهُۥ","his scales"],["فَأُو۟لَـٰٓئِكَ","so those"],["ٱلَّذِينَ","(will be) the ones who"],["خَسِرُوٓا۟","lost"],["أَنفُسَهُم","themselves"],["بِمَا","because"],["كَانُوا۟","they were"],["بِـَٔايَـٰتِنَا","to Our Verses"],["يَظْلِمُونَ","(doing) injustice"]]],"964":["(Sesungguhnya Kami telah menempatkan kamu sekalian) hai anak-anak Adam (di muka bumi dan Kami adakan bagimu di muka bumi itu sumber-sumber penghidupan) dengan memakai huruf ya, yakni sarana-sarana untuk kamu bisa hidup. Ma`ayisy jamak dari kata ma'isyah (amat sedikitlah) untuk mengukuhkan keminiman (kamu bersyukur) terhadap kesemuanya itu.",[["وَلَقَدْ","And certainly"],["مَكَّنَّـٰكُمْ","We established you"],["فِى","in"],["ٱلْأَرْضِ","the earth"],["وَجَعَلْنَا","and We made"],["لَكُمْ","for you"],["فِيهَا","in it"],["مَعَـٰيِشَ ۗ","livelihood"],["قَلِيلًۭا","Little"],["مَّا","(is) what"],["تَشْكُرُونَ","you (are) grateful"]]],"965":["(Sesungguhnya Kami telah menciptakanmu) maksudnya ayah kamu yaitu Adam (lalu Kami bentuk tubuhmu) Kami membentuk tubuhnya sedangkan kamu masih berada di dalam sulbinya (kemudian Kami katakan kepada para malaikat, \"Bersujudlah kamu kepada Adam,\") sebagai penghormatan, yaitu dengan menundukkan punggung (maka mereka pun bersujud kecuali iblis) yaitu kakek moyang bangsa jin yang ada di antara malaikat (dia tidak termasuk mereka yang bersujud).",[["وَلَقَدْ","And certainly"],["خَلَقْنَـٰكُمْ","We created you"],["ثُمَّ","then"],["صَوَّرْنَـٰكُمْ","We fashioned you"],["ثُمَّ","Then"],["قُلْنَا","We said"],["لِلْمَلَـٰٓئِكَةِ","to the Angels"],["ٱسْجُدُوا۟","Prostrate"],["لِـَٔادَمَ","to Adam"],["فَسَجَدُوٓا۟","So they prostrated"],["إِلَّآ","except"],["إِبْلِيسَ","Iblis"],["لَمْ","Not"],["يَكُن","he was"],["مِّنَ","of"],["ٱلسَّـٰجِدِينَ","those who prostrated"]]],"966":["(Allah berfirman,) Maha Tinggi Allah, (\"Apakah yang menghalangimu untuk) huruf laa adalah tambahan (bersujud di waktu) tatkala (Aku menyuruhmu.\" Menjawab iblis, \"Aku lebih baik daripadanya, Engkau ciptakan aku dari api sedangkan dia Engkau ciptakan dari tanah.\")",[["قَالَ","(Allah) said"],["مَا","What"],["مَنَعَكَ","prevented you"],["أَلَّا","that not"],["تَسْجُدَ","you prostrate"],["إِذْ","when"],["أَمَرْتُكَ ۖ","I commanded you"],["قَالَ","(Shaitaan) said"],["أَنَا۠","I am"],["خَيْرٌۭ","better"],["مِّنْهُ","than him"],["خَلَقْتَنِى","You created me"],["مِن","from"],["نَّارٍۢ","fire"],["وَخَلَقْتَهُۥ","and You created him"],["مِن","from"],["طِينٍۢ","clay"]]],"967":["(Allah berfirman, \"Turunlah kamu dari surga itu) ada yang mengatakan dari langit (karena tidak patut) tidak layak (bagi kamu menyombongkan diri di dalamnya, maka keluarlah) dari surga (sesungguhnya kamu termasuk orang-orang yang hina.\") maksudnya orang-orang yang terhina.",[["قَالَ","(Allah) said"],["فَٱهْبِطْ","Then go down"],["مِنْهَا","from it"],["فَمَا","for not"],["يَكُونُ","it is"],["لَكَ","for you"],["أَن","that"],["تَتَكَبَّرَ","you be arrogant"],["فِيهَا","in it"],["فَٱخْرُجْ","So get out"],["إِنَّكَ","indeed, you"],["مِنَ","(are) of"],["ٱلصَّـٰغِرِينَ","the disgraced ones"]]],"968":["(Iblis menjawab, \"Beri tangguhlah saya) artinya berilah saya kesempatan (sampai waktu mereka dibangkitkan.\") yakni sampai manusia dibangkitkan.",[["قَالَ","(Shaitaan) said"],["أَنظِرْنِىٓ","Give me respite"],["إِلَىٰ","till"],["يَوْمِ","(the) Day"],["يُبْعَثُونَ","they are raised up"]]],"969":["(Allah berfirman, \"Sesungguhnya kamu termasuk mereka yang diberi tangguh.\") pada ayat lain disebutkan, \"Hingga hari yang telah ditentukan,\" yaitu waktu ditiupnya sangkakala pertama.",[["قَالَ","(Allah) said"],["إِنَّكَ","Indeed, you"],["مِنَ","(are) of"],["ٱلْمُنظَرِينَ","the ones given respite"]]],"970":["(Iblis menjawab, \"Karena Engkau telah menyesatkan saya) Engkau telah menghukum saya; huruf ba mengandung makna qasam/sumpah dan sebagai jawabnya ialah (saya benar-benar akan menghalang-halangi mereka) yaitu anak-anak Adam (dari jalan Engkau yang lurus) maksudnya dari jalan yang dapat mempertemukan mereka kepada Engkau.",[["قَالَ","(Shaitaan) said"],["فَبِمَآ","Because"],["أَغْوَيْتَنِى","You have sent me astray"],["لَأَقْعُدَنَّ","surely I will sit"],["لَهُمْ","for them"],["صِرَٰطَكَ","(on) Your path"],["ٱلْمُسْتَقِيمَ","the straight"]]],"971":["(Kemudian saya akan mendatangi mereka dari muka dan dari belakang, dari kanan dan dari kiri mereka) maksudnya dari segala penjuru, kemudian aku halang-halangi mereka untuk bisa menempuh jalan-Mu itu. Akan tetapi Ibnu Abbas memberikan penafsirannya, bahwa iblis tidak akan dapat mendatangi mereka dari arah atasnya hal itu supaya ia jangan menghalang-halangi jalan antara hamba dengan rahmat Allah swt. (dan engkau tidak akan mendapati kebanyakan mereka bersyukur\") yakni beriman.",[["ثُمَّ","Then"],["لَـَٔاتِيَنَّهُم","surely, I will come to them"],["مِّنۢ","from"],["بَيْنِ","before"],["أَيْدِيهِمْ","them"],["وَمِنْ","and from"],["خَلْفِهِمْ","behind them"],["وَعَنْ","and from"],["أَيْمَـٰنِهِمْ","their right"],["وَعَن","and from"],["شَمَآئِلِهِمْ ۖ","their left"],["وَلَا","and not"],["تَجِدُ","You (will) find"],["أَكْثَرَهُمْ","most of them"],["شَـٰكِرِينَ","grateful"]]],"972":["(Allah berfirman, \"Keluarlah kamu dari surga itu sebagai orang yang terhina) dengan memakai hamzah, artinya tercela atau kena murka Allah (lagi terusir) dijauhkan dari rahmat Allah. (Sesungguhnya barang siapa di antara mereka mengikuti kamu) dari kalangan umat manusia; huruf lam menunjukkan makna ibtida/permulaan kalimat atau sebagai pendahuluan dari qasam/sumpah, yang mana sumpahnya adalah (sungguh Aku akan memenuhi neraka Jahanam dengan kamu semuanya\") yakni kamu dan anak-cucumu serta manusia. Di dalam ayat ini terkandung makna taghliibul haadhir `alal ghaaib atau mengutamakan yang hadir daripada yang tidak hadir; jumlah ini mengandung makna syarat, yakni: Barang siapa yang mengikutimu Aku akan menyiksanya.",[["قَالَ","(Allah) said"],["ٱخْرُجْ","Get out"],["مِنْهَا","of it"],["مَذْءُومًۭا","disgraced"],["مَّدْحُورًۭا ۖ","and expelled"],["لَّمَن","Certainly, whoever"],["تَبِعَكَ","follows you"],["مِنْهُمْ","among them"],["لَأَمْلَأَنَّ","surely, I will fill"],["جَهَنَّمَ","Hell"],["مِنكُمْ","with you"],["أَجْمَعِينَ","all"]]],"973":["(Dan) Allah berfirman (\"Hai Adam bertempat tinggallah kamu) lafal anta merupakan pengukuhan terhadap dhamir yang terdapat di dalam lafal uskun, tujuannya ialah untuk dijadikan sebagai ma'thuf alaih (dan istrimu) yakni Hawa, dengan dibaca panjang (di surga serta makanlah olehmu berdua buah-buahan mana saja yang kamu sukai, dan janganlah kamu berdua mendekati pohon ini) dengan cara memakannya, yang dimaksud adalah pohon gandum (maka menjadilah kamu berdua termasuk orang-orang yang lalim\").",[["وَيَـٰٓـَٔادَمُ","And O Adam"],["ٱسْكُنْ","Dwell"],["أَنتَ","you"],["وَزَوْجُكَ","and your wife"],["ٱلْجَنَّةَ","(in) the Garden"],["فَكُلَا","and you both eat"],["مِنْ","from"],["حَيْثُ","wherever"],["شِئْتُمَا","you both wish"],["وَلَا","but (do) not"],["تَقْرَبَا","approach [both of you]"],["هَـٰذِهِ","this"],["ٱلشَّجَرَةَ","[the] tree"],["فَتَكُونَا","lest you both be"],["مِنَ","among"],["ٱلظَّـٰلِمِينَ","the wrongdoers"]]],"974":["(Maka setan mulai menggoda keduanya) yakni iblis (untuk menampakkan) memperlihatkan (kepada keduanya apa yang tertutup) dengan wazan fu`ila dari lafal al-muwaaraah (dari mereka, yaitu auratnya dan setan berkata, \"Tuhan kamu tidak melarangmu dari mendekati pohon ini melainkan) karena khawatir (supaya kamu berdua tidak menjadi malaikat) dan menurut suatu qiraat dibaca dengan malikaini/lam dikasrahkan (atau tidak menjadi orang-orang yang kekal dalam surga\") berdasarkan hal itu maka memakan pohon itu adalah suatu keharusan sebagaimana yang disebutkan pula di dalam ayat lain, yaitu, \"Maukah saya tunjukkan kepada kamu pohon kekekalan dan kerajaan yang tidak akan binasa.\" (Q.S. Thaha 120)",[["فَوَسْوَسَ","Then whispered"],["لَهُمَا","to both of them"],["ٱلشَّيْطَـٰنُ","the Shaitaan"],["لِيُبْدِىَ","to make apparent"],["لَهُمَا","to both of them"],["مَا","what"],["وُۥرِىَ","was concealed"],["عَنْهُمَا","from both of them"],["مِن","of"],["سَوْءَٰتِهِمَا","their shame"],["وَقَالَ","And he said"],["مَا","(Did) not"],["نَهَىٰكُمَا","forbid you both"],["رَبُّكُمَا","your Lord"],["عَنْ","from"],["هَـٰذِهِ","this"],["ٱلشَّجَرَةِ","[the] tree"],["إِلَّآ","except"],["أَن","that"],["تَكُونَا","you two become"],["مَلَكَيْنِ","Angels"],["أَوْ","or"],["تَكُونَا","you two become"],["مِنَ","of"],["ٱلْخَـٰلِدِينَ","the immortals"]]],"975":["(Dan dia, setan, bersumpah kepada keduanya) setan bersumpah dengan nama Allah kepada keduanya (\"Sesungguhnya saya adalah termasuk orang yang memberi nasihat kepada kamu berdua.\") di dalam hal ini.",[["وَقَاسَمَهُمَآ","And he swore (to) both of them"],["إِنِّى","Indeed, I am"],["لَكُمَا","to both of you"],["لَمِنَ","among"],["ٱلنَّـٰصِحِينَ","the sincere advisors"]]],"976":["(Maka setan membujuk keduanya) untuk menurunkan kedudukan keduanya (dengan tipu daya) darinya. (Tatkala keduanya telah merasai buah pohon itu) mereka berdua telah memakannya (nampaklah bagi keduanya aurat-auratnya) yakni kedua kemaluan masing-masing tampak oleh lainnya; kedua anggota tubuh itu dinamakan sau`ah, sebab jika terbuka akan membuat malu orang yang bersangkutan (dan mulailah keduanya menutupi) maksud keduanya mengambil penutup untuk menutupi (kedua auratnya dengan daun-daun surga) untuk menutupinya. (Kemudian Tuhan mereka menyeru mereka, \"Bukankah Aku telah melarang kamu berdua dari pohon itu dan Aku katakan kepadamu, 'Sesungguhnya setan itu adalah musuh yang nyata bagi kamu berdua.')\" yang jelas permusuhannya; kata tanya menunjukkan makna penegasan.",[["فَدَلَّىٰهُمَا","So he made both of them fall"],["بِغُرُورٍۢ ۚ","by deception"],["فَلَمَّا","Then when"],["ذَاقَا","they both tasted"],["ٱلشَّجَرَةَ","the tree"],["بَدَتْ","became apparent"],["لَهُمَا","to both of them"],["سَوْءَٰتُهُمَا","their shame"],["وَطَفِقَا","and they began"],["يَخْصِفَانِ","(to) fasten"],["عَلَيْهِمَا","over themselves"],["مِن","from"],["وَرَقِ","(the) leaves"],["ٱلْجَنَّةِ ۖ","(of) the Garden"],["وَنَادَىٰهُمَا","And called them both"],["رَبُّهُمَآ","their Lord"],["أَلَمْ","Did not"],["أَنْهَكُمَا","I forbid you both"],["عَن","from"],["تِلْكُمَا","this"],["ٱلشَّجَرَةِ","[the] tree"],["وَأَقُل","and [I] say"],["لَّكُمَآ","to both of you"],["إِنَّ","that"],["ٱلشَّيْطَـٰنَ","[the] Shaitaan"],["لَكُمَا","to both of you"],["عَدُوٌّۭ","(is) an enemy"],["مُّبِينٌۭ","open"]]],"977":["(Keduanya berkata, \"Ya Tuhan kami, kami telah menganiaya diri kami sendiri) oleh sebab perbuatan maksiat kami berdua (dan jika Engkau tidak mengampuni kami dan memberi rahmat kepada kami, niscaya pastilah kami termasuk orang-orang yang merugi.\")",[["قَالَا","Both of them said"],["رَبَّنَا","Our Lord"],["ظَلَمْنَآ","we have wronged"],["أَنفُسَنَا","ourselves"],["وَإِن","and if"],["لَّمْ","not"],["تَغْفِرْ","You forgive"],["لَنَا","[for] us"],["وَتَرْحَمْنَا","and have mercy (on) us"],["لَنَكُونَنَّ","surely, we will be"],["مِنَ","among"],["ٱلْخَـٰسِرِينَ","the losers"]]],"978":["(Allah berfirman, \"Turunlah kamu sekalian) yakni Adam dan Hawa serta anak-cucu kamu yang masih berada di dalam diri kamu (sebagian kamu) maksudnya sebagian keturunan (menjadi musuh bagi sebagian yang lain) sebagian mereka berlaku aniaya terhadap sebagian yang lainnya. (Dan kamu di muka bumi mempunyai tempat kediaman) yaitu tempat tinggal (dan kesenangan) tempat bersenang-senang (sampai waktu yang ditentukan.\") apabila ajal kamu telah sampai pada saatnya.",[["قَالَ","(Allah) said"],["ٱهْبِطُوا۟","Get down"],["بَعْضُكُمْ","some of you"],["لِبَعْضٍ","to some others"],["عَدُوٌّۭ ۖ","(as) enemy"],["وَلَكُمْ","And for you"],["فِى","in"],["ٱلْأَرْضِ","the earth"],["مُسْتَقَرٌّۭ","(is) a dwelling place"],["وَمَتَـٰعٌ","and livelihood"],["إِلَىٰ","for"],["حِينٍۢ","a time"]]],"979":["(Allah berfirman, \"Di muka bumi itu kamu hidup dan di muka bumi itu kamu mati, dan dari bumi itu pula kamu akan dikeluarkan\") dibangkitkan, dengan memakai bina fa`il dan bina maf`ul atau bentuk aktif dan bentuk pasif.",[["قَالَ","He said"],["فِيهَا","In it"],["تَحْيَوْنَ","you will live"],["وَفِيهَا","and in it"],["تَمُوتُونَ","you will die"],["وَمِنْهَا","and from it"],["تُخْرَجُونَ","you will be brought forth"]]],"980":["(Hai anak Adam! Sesungguhnya Kami telah menurunkan kepadamu pakaian) Kami telah menciptakannya untuk kamu (untuk menutupi) guna menutupi (auratmu dan pakaian perhiasan) pakaian yang digunakan sebagai perhiasan. (Dan pakaian takwa) yakni amal saleh dan akhlak yang baik; dengan dibaca nashab karena diathafkan kepada lafal libaasan, dan dibaca rafa' sebagai mubtada sedangkan khabarnya ialah jumlah berikut ini (itulah yang lebih baik. Yang demikian itu adalah sebagian tanda-tanda kekuasaan Allah) bukti-bukti yang menunjukkan kekuasaan-Nya (mudah-mudahan mereka selalu ingat) kemudian mau beriman; di dalam jumlah ini terkandung iltifat atau kata sindiran terhadap mukhathab atau orang yang diajak bicara.",[["يَـٰبَنِىٓ","O Children"],["ءَادَمَ","(of) Adam"],["قَدْ","Verily"],["أَنزَلْنَا","We have sent down"],["عَلَيْكُمْ","to you"],["لِبَاسًۭا","clothing"],["يُوَٰرِى","it covers"],["سَوْءَٰتِكُمْ","your shame"],["وَرِيشًۭا ۖ","and (as) an adornment"],["وَلِبَاسُ","But the clothing"],["ٱلتَّقْوَىٰ","(of) [the] righteousness "],["ذَٰلِكَ","that"],["خَيْرٌۭ ۚ","(is) best"],["ذَٰلِكَ","That"],["مِنْ","(is) from"],["ءَايَـٰتِ","(the) Signs"],["ٱللَّهِ","(of) Allah"],["لَعَلَّهُمْ","so that they may"],["يَذَّكَّرُونَ","remember"]]],"981":["(Hai anak Adam janganlah sekali-kali kamu dapat ditipu) disesatkan (oleh setan) janganlah kamu mengikuti setan sehingga akibatnya kamu akan tertipu (sebagaimana ia telah mengeluarkan ibu-bapakmu) dengan senjata tipu-dayanya (dari surga, di mana ia menanggalkan) menjadi hal (daripada keduanya yaitu pakaian mereka berdua untuk memperlihatkan kepada keduanya aurat masing-masing. Sesungguhnya ia) yakni setan itu (dan pengikut-pengikutnya melihat kamu) yaitu bala tentaranya (dari suatu tempat yang kamu tidak bisa melihat mereka) karena kehalusan jasad mereka atau karena mereka tidak berwarna. (Sesungguhnya Kami telah menjadikan setan-setan itu pemimpin-pemimpin) artinya pendukung-pendukung dan teman-teman (bagi orang-orang yang tidak beriman).",[["يَـٰبَنِىٓ","O Children"],["ءَادَمَ","(of) Adam"],["لَا","(Let) not"],["يَفْتِنَنَّكُمُ","tempt you"],["ٱلشَّيْطَـٰنُ","[the] Shaitaan"],["كَمَآ","as"],["أَخْرَجَ","he drove out"],["أَبَوَيْكُم","your parents"],["مِّنَ","from"],["ٱلْجَنَّةِ","Paradise"],["يَنزِعُ","stripping"],["عَنْهُمَا","from both of them"],["لِبَاسَهُمَا","their clothing"],["لِيُرِيَهُمَا","to show both of them"],["سَوْءَٰتِهِمَآ ۗ","their shame"],["إِنَّهُۥ","Indeed, he"],["يَرَىٰكُمْ","sees you "],["هُوَ","he"],["وَقَبِيلُهُۥ","and his tribe"],["مِنْ","from"],["حَيْثُ","where"],["لَا","not"],["تَرَوْنَهُمْ ۗ","you see them"],["إِنَّا","Indeed"],["جَعَلْنَا","We have made"],["ٱلشَّيَـٰطِينَ","the devils"],["أَوْلِيَآءَ","friends"],["لِلَّذِينَ","of those who"],["لَا","(do) not"],["يُؤْمِنُونَ","believe"]]],"982":["(Dan apabila mereka melakukan perbuatan keji) seperti perbuatan syirik dan tawaf mereka di sekeliling Kakbah dalam keadaan telanjang seraya mengemukakan alasan mereka, \"Kami tidak akan melakukan tawaf dengan pakaian yang biasa kami gunakan untuk maksiat.\" Kemudian mereka dilarang dari perbuatan tersebut (mereka berkata, \"Kami mendapati nenek-moyang kami mengerjakan yang demikian itu) kami hanya mengikut kepada mereka (dan Allah menyuruh kami mengerjakannya.\") juga. (Katakanlah) kepada mereka (\"Sesungguhnya Allah tidak menyuruh mengadakan perbuatan yang keji.\" Mengapa kamu mengada-adakan terhadap Allah apa yang tidak kamu ketahui?) bahwa Allah mengatakannya; istifham atau kata tanya di sini menunjukkan makna ingkar atau sanggahan.",[["وَإِذَا","And when"],["فَعَلُوا۟","they do"],["فَـٰحِشَةًۭ","immorality"],["قَالُوا۟","they say"],["وَجَدْنَا","We found"],["عَلَيْهَآ","on it"],["ءَابَآءَنَا","our forefathers"],["وَٱللَّهُ","and Allah"],["أَمَرَنَا","(has) ordered us"],["بِهَا ۗ","of it"],["قُلْ","Say"],["إِنَّ","Indeed"],["ٱللَّهَ","Allah"],["لَا","(does) not"],["يَأْمُرُ","order"],["بِٱلْفَحْشَآءِ ۖ","immorality"],["أَتَقُولُونَ","Do you say"],["عَلَى","about"],["ٱللَّهِ","Allah"],["مَا","what"],["لَا","not"],["تَعْلَمُونَ","you know"]]],"983":["(Katakanlah, \"Tuhanku menyuruh menjalankan keadilan\") yaitu perbuatan yang adil. (Dan luruskanlah) diathafkan secara makna kepada lafal bil qisthi, yang artinya, Ia berkata, \"Berlaku adillah kamu dan luruskanlah dirimu.\" Atau diathafkan kepada lafal sebelumnya dengan menyimpan taqdir yakni: Hadapkanlah dirimu (mukamu) kepada Allah (di setiap salatmu) ikhlaslah kamu kepada-Nya di dalam sujudmu (dan sembahlah Allah) beribadahlah kepada-Nya (dengan mengikhlaskan ketaatan kepada-Nya) bersih dari kemusyrikan. (Sebagaimana Dia menciptakanmu pada permulaan) yang sebelumnya kamu bukanlah merupakan sesuatu (demikian pulalah akan kembali kepada-Nya) artinya Dia akan mengembalikan kamu pada hari kiamat dalam keadaan hidup kembali.",[["قُلْ","Say"],["أَمَرَ","(Has been) ordered"],["رَبِّى","(by) my Lord"],["بِٱلْقِسْطِ ۖ","justice"],["وَأَقِيمُوا۟","and set"],["وُجُوهَكُمْ","your faces"],["عِندَ","at"],["كُلِّ","every"],["مَسْجِدٍۢ","masjid"],["وَٱدْعُوهُ","and invoke Him"],["مُخْلِصِينَ","(being) sincere"],["لَهُ","to Him"],["ٱلدِّينَ ۚ","(in) the religion"],["كَمَا","As"],["بَدَأَكُمْ","He originated you"],["تَعُودُونَ","(so) will you return"]]],"984":["(Sebagian) dari kamu (diberi-Nya petunjuk dan sebagian lagi telah pasti kesesatan bagi mereka. Sesungguhnya mereka menjadikan setan-setan pelindung mereka selain Allah) (dan mereka mengira bahwa mereka mendapat petunjuk).",[["فَرِيقًا","A group"],["هَدَىٰ","He guided"],["وَفَرِيقًا","and a group"],["حَقَّ","deserved "],["عَلَيْهِمُ","[on] they"],["ٱلضَّلَـٰلَةُ ۗ","the astraying"],["إِنَّهُمُ","Indeed, they"],["ٱتَّخَذُوا۟","take"],["ٱلشَّيَـٰطِينَ","the devils"],["أَوْلِيَآءَ","(as) allies"],["مِن","from"],["دُونِ","besides"],["ٱللَّهِ","Allah"],["وَيَحْسَبُونَ","while they think"],["أَنَّهُم","that they"],["مُّهْتَدُونَ","(are the) guided-ones"]]],"985":["(Hai anak Adam, pakailah pakaianmu yang indah) yaitu buat menutupi auratmu (di setiap memasuki mesjid) yaitu di kala hendak melakukan salat dan tawaf (makan dan minumlah) sesukamu (dan janganlah berlebih-lebihan. Sesungguhnya Allah tidak menyukai orang yang berlebih-lebihan).",[["۞ يَـٰبَنِىٓ","O Children"],["ءَادَمَ","(of) Adam"],["خُذُوا۟","Take"],["زِينَتَكُمْ","your adornment"],["عِندَ","at"],["كُلِّ","every"],["مَسْجِدٍۢ","masjid"],["وَكُلُوا۟","and eat"],["وَٱشْرَبُوا۟","and drink"],["وَلَا","but (do) not"],["تُسْرِفُوٓا۟ ۚ","be extravagant"],["إِنَّهُۥ","Indeed, He"],["لَا","(does) not"],["يُحِبُّ","love"],["ٱلْمُسْرِفِينَ","the extravagant ones"]]],"986":["(Katakanlah,) sebagai rasa ingkar kepada mereka (\"Siapakah yang mengharamkan perhiasan dari Allah yang telah dikeluarkan-Nya untuk hamba-hamba-Nya) yang terdiri dari pakaian (dan yang baik-baik) yakni kelezatan-kelezatan (dari rezeki?\" Katakanlah, \"Semuanya itu disediakan bagi orang-orang yang beriman dalam kehidupan dunia) yang berhak memilikinya sekalipun selain mereka turut pula memilikinya (khusus) khusus untuk mereka saja; dengan dibaca rafa` sedangkan dibaca nashab menjadi hal (di hari kiamat.\" Demikianlah Kami menjelaskan ayat-ayat itu) maksudnya Kami menerangkan hal itu sedemikian terincinya (bagi orang-orang yang mengetahui) yaitu mereka yang mau menggunakan pikirannya sebab hanya merekalah yang dapat memanfaatkannya secara baik.",[["قُلْ","Say"],["مَنْ","Who"],["حَرَّمَ","has forbidden"],["زِينَةَ","(the) adornment"],["ٱللَّهِ","(from) Allah"],["ٱلَّتِىٓ","which"],["أَخْرَجَ","He has brought forth"],["لِعِبَادِهِۦ","for His slaves"],["وَٱلطَّيِّبَـٰتِ","and the pure things"],["مِنَ","of"],["ٱلرِّزْقِ ۚ","sustenance"],["قُلْ","Say"],["هِىَ","They"],["لِلَّذِينَ","(are) for those who"],["ءَامَنُوا۟","believe"],["فِى","during"],["ٱلْحَيَوٰةِ","the life"],["ٱلدُّنْيَا","(of) the world"],["خَالِصَةًۭ","exclusively (for them)"],["يَوْمَ","(on the) Day"],["ٱلْقِيَـٰمَةِ ۗ","(of) Resurrection"],["كَذَٰلِكَ","Thus"],["نُفَصِّلُ","We explain"],["ٱلْـَٔايَـٰتِ","the Signs"],["لِقَوْمٍۢ","for (the) people"],["يَعْلَمُونَ","who know"]]],"987":["(Katakanlah, \"Tuhanku hanya mengharamkan perbuatan yang keji) yaitu dosa-dosa besar seperti perbuatan zina (baik yang tampak atau pun yang tersembunyi) yang terang-terangan atau pun yang sifatnya rahasia (dan perbuatan dosa) perbuatan maksiat (melanggar hak) orang lain (tanpa alasan yang benar) perbuatan lalim (mempersekutukan Allah dengan sesuatu yang Allah tidak menurunkan tentangnya) memusyrikkan-Nya (suatu kekuasaan pun) suatu hujah pun (dan mengharamkan mengada-adakan terhadap Allah apa yang tidak kamu ketahui.\") yaitu mengharamkan apa yang tidak diharamkan dan lain sebagainya.",[["قُلْ","Say"],["إِنَّمَا","Only"],["حَرَّمَ","(had) forbidden"],["رَبِّىَ","my Lord"],["ٱلْفَوَٰحِشَ","the shameful deeds"],["مَا","what"],["ظَهَرَ","(is) apparent"],["مِنْهَا","of it"],["وَمَا","and what"],["بَطَنَ","is concealed"],["وَٱلْإِثْمَ","and the sin"],["وَٱلْبَغْىَ","and the oppression"],["بِغَيْرِ","without"],["ٱلْحَقِّ","[the] right"],["وَأَن","and that"],["تُشْرِكُوا۟","you associate (others)"],["بِٱللَّهِ","with Allah"],["مَا","what"],["لَمْ","not"],["يُنَزِّلْ","He (has) sent down"],["بِهِۦ","of it"],["سُلْطَـٰنًۭا","any authority"],["وَأَن","and that"],["تَقُولُوا۟","you say"],["عَلَى","about"],["ٱللَّهِ","Allah"],["مَا","what"],["لَا","not"],["تَعْلَمُونَ","you know"]]],"988":["(Tiap-tiap umat mempunyai ajal) yakni masa tertentu (maka apabila telah datang ajalnya, mereka tidak dapat mengundurkannya) ajal itu (barang sesaat pun dan tidak dapat pula memajukannya) memajukan temponya.",[["وَلِكُلِّ","And for every"],["أُمَّةٍ","nation"],["أَجَلٌۭ ۖ","(is a fixed) term"],["فَإِذَا","So when"],["جَآءَ","comes"],["أَجَلُهُمْ","their term"],["لَا","(they can) not"],["يَسْتَأْخِرُونَ","seek to delay"],["سَاعَةًۭ ۖ","an hour"],["وَلَا","and not"],["يَسْتَقْدِمُونَ","seek to advance (it)"]]],"989":["(Hai anak-anak Adam, jika) lafal immaa merupakan gabungan antara in syarthiah dan maa zaaidah atau tambahan (datang kepadamu rasul-rasul daripada kamu yang menceritakan kepadamu ayat-ayat-Ku, maka siapa yang bertakwa) menjauhkan diri dari kemusyrikan (dan mengadakan perbaikan) amal perbuatannya (tidaklah ada kekhawatiran terhadap mereka dan tidak pula mereka bersedih hati) di akhirat kelak.",[["يَـٰبَنِىٓ","O Children"],["ءَادَمَ","(of) Adam"],["إِمَّا","If"],["يَأْتِيَنَّكُمْ","come to you"],["رُسُلٌۭ","Messengers"],["مِّنكُمْ","from you"],["يَقُصُّونَ","relating"],["عَلَيْكُمْ","to you"],["ءَايَـٰتِى ۙ","My Verses"],["فَمَنِ","then whoever"],["ٱتَّقَىٰ","fears Allah"],["وَأَصْلَحَ","and reforms"],["فَلَا","then no"],["خَوْفٌ","fear"],["عَلَيْهِمْ","on them"],["وَلَا","and not"],["هُمْ","they"],["يَحْزَنُونَ","will grieve"]]],"990":["(Dan orang-orang yang mendustakan ayat-ayat Kami dan menyombongkan diri) berlaku takabur (terhadapnya) sehingga mereka tidak mau percaya kepadanya (mereka itu penghuni-penghuni neraka; mereka kekal di dalamnya).",[["وَٱلَّذِينَ","But those who"],["كَذَّبُوا۟","deny"],["بِـَٔايَـٰتِنَا","Our Verses"],["وَٱسْتَكْبَرُوا۟","and (are) arrogant"],["عَنْهَآ","towards them"],["أُو۟لَـٰٓئِكَ","those"],["أَصْحَـٰبُ","(are the) companions"],["ٱلنَّارِ ۖ","(of) the Fire"],["هُمْ","they"],["فِيهَا","in it"],["خَـٰلِدُونَ","will abide forever"]]],"991":["(Maka siapakah) maksudnya tidak ada seorang pun (yang lebih lalim daripada orang yang membuat-buat dusta terhadap Allah) dengan mengatakan bahwa Allah itu mempunyai sekutu atau Ia beranak (atau mendustakan ayat-ayat-Nya?) yakni Alquran. (Orang-orang itu akan memperoleh) mereka tetap akan mendapat (bagian mereka) yakni bagian yang telah ditentukan untuknya (dalam Alkitab) yaitu apa-apa yang telah dipastikan dan tertulis untuk mereka di Lohmahfuz berupa rezeki, ajal dan lain-lainnya (sehingga bila datang kepada mereka utusan-utusan Kami) para malaikat (untuk mengambil nyawa mereka seraya mengatakan,) kepada mereka dengan nada mengejek (\"Di mana berhala-berhala yang biasa kamu sembah) sesembahan-sesembahan yang selalu kamu puja-puja (selain Allah.\" Mereka menjawab, \"Berhala-berhala itu telah lenyap) telah hilang (dari kami) sehingga kami tidak dapat melihatnya (dan mereka mengakui terhadap diri mereka) di kala menjelang ajalnya (bahwa mereka adalah orang-orang yang kafir\").",[["فَمَنْ","Then who"],["أَظْلَمُ","(is) more unjust"],["مِمَّنِ","than (one) who"],["ٱفْتَرَىٰ","invented"],["عَلَى","against"],["ٱللَّهِ","Allah"],["كَذِبًا","a lie"],["أَوْ","or"],["كَذَّبَ","denies"],["بِـَٔايَـٰتِهِۦٓ ۚ","His Verses"],["أُو۟لَـٰٓئِكَ","Those "],["يَنَالُهُمْ","will reach them"],["نَصِيبُهُم","their portion"],["مِّنَ","from"],["ٱلْكِتَـٰبِ ۖ","the Book"],["حَتَّىٰٓ","until"],["إِذَا","when"],["جَآءَتْهُمْ","comes to them"],["رُسُلُنَا","Our messengers (Angels)"],["يَتَوَفَّوْنَهُمْ","(to) take them in death"],["قَالُوٓا۟","they say"],["أَيْنَ","Where are"],["مَا","those (whom)"],["كُنتُمْ","you used to"],["تَدْعُونَ","invoke"],["مِن","from"],["دُونِ","besides"],["ٱللَّهِ ۖ","Allah"],["قَالُوا۟","They say"],["ضَلُّوا۟","They strayed"],["عَنَّا","from us"],["وَشَهِدُوا۟","and they (will) testify"],["عَلَىٰٓ","against"],["أَنفُسِهِمْ","themselves"],["أَنَّهُمْ","that they"],["كَانُوا۟","were"],["كَـٰفِرِينَ","disbelievers"]]],"992":["(Allah berfirman,) Maha Tinggi Allah; Dia berfirman kepada mereka kelak di hari kiamat (\"Masuklah kamu sekalian ke dalam) golongan (umat-umat yang telah terdahulu sebelum kamu dari kalangan jin dan manusia ke dalam neraka\") Jar dan majrurnya berta'alluq pada lafal udkhuluu. (Setiap umat yang masuk) ke dalam neraka (dia mengutuk kawannya) yang sebelumnya telah menyesatkannya (sehingga apabila mereka masuk) menyusul kawan-kawannya (ke dalam neraka semuanya, berkatalah orang-orang yang masuk kemudian) mereka adalah orang-orang yang hanya mengikuti (kepada orang-orang yang masuk terdahulu) maksudnya para penghulu mereka yang menjadi panutan (\"Ya Tuhan kami, mereka telah menyesatkan kami, sebab itu datangkanlah kepada mereka siksaan yang berlipat ganda) yang berkali-kali lipat (dari neraka.\" Allah berfirman,) Maha Tinggi Allah (\"Masing-masing) dari kamu dan dari mereka (mendapat siksaan yang berlipat ganda) maksudnya azab yang berlipat ganda (akan tetapi mereka tidak mengetahui.\") dengan memakai ya dan ta; mereka tidak mengetahui siksaan apa yang diterima oleh masing-masing golongan.",[["قَالَ","He (will) say"],["ٱدْخُلُوا۟","Enter"],["فِىٓ","among"],["أُمَمٍۢ","(the) nations"],["قَدْ","(who)"],["خَلَتْ","passed away"],["مِن","from"],["قَبْلِكُم","before you"],["مِّنَ","of"],["ٱلْجِنِّ","the jinn"],["وَٱلْإِنسِ","and the men"],["فِى","in"],["ٱلنَّارِ ۖ","the Fire"],["كُلَّمَا","Every time"],["دَخَلَتْ","entered"],["أُمَّةٌۭ","a nation"],["لَّعَنَتْ","it cursed"],["أُخْتَهَا ۖ","its sister (nation)"],["حَتَّىٰٓ","until"],["إِذَا","when"],["ٱدَّارَكُوا۟","they had overtaken one another"],["فِيهَا","in it"],["جَمِيعًۭا","all"],["قَالَتْ","(will) say"],["أُخْرَىٰهُمْ","(the) last of them"],["لِأُولَىٰهُمْ","about the first of them"],["رَبَّنَا","Our Lord"],["هَـٰٓؤُلَآءِ","these"],["أَضَلُّونَا","misled us"],["فَـَٔاتِهِمْ","so give them"],["عَذَابًۭا","punishment"],["ضِعْفًۭا","double"],["مِّنَ","of"],["ٱلنَّارِ ۖ","the Fire"],["قَالَ","He (will) say"],["لِكُلٍّۢ","For each"],["ضِعْفٌۭ","(is) a double"],["وَلَـٰكِن","[and] but"],["لَّا","not"],["تَعْلَمُونَ","you know"]]],"993":["(Dan berkata orang-orang yang masuk terdahulu di antara mereka kepada orang-orang yang masuk kemudian, \"Kamu tidak mempunyai kelebihan sedikit pun atas kami\") sebab kamu ikut kafir seperti kami, maka kami dan kamu adalah sama, kemudian Allah berfirman kepada mereka semua, (maka rasakanlah siksaan dari perbuatan yang telah kamu lakukan).",[["وَقَالَتْ","And (will) say"],["أُولَىٰهُمْ","(the) first of them"],["لِأُخْرَىٰهُمْ","to (the) last of them"],["فَمَا","Then not"],["كَانَ","is"],["لَكُمْ","for you"],["عَلَيْنَا","upon us"],["مِن","any"],["فَضْلٍۢ","superiority"],["فَذُوقُوا۟","so taste"],["ٱلْعَذَابَ","the punishment"],["بِمَا","for what"],["كُنتُمْ","you used to"],["تَكْسِبُونَ","earn"]]],"994":["(Sesungguhnya orang-orang yang mendustakan ayat-ayat Kami dan menyombongkan diri) mereka berlaku sombong (terhadapnya) kemudian mereka tidak mau percaya terhadapnya (sekali-kali tidak akan dibukakan bagi mereka pintu-pintu langit) yaitu apabila arwah-arwah mereka dinaikkan sesudah mati, sehingga arwah mereka turun kembali ke Sijjin atau neraka yang ada di dalam perut bumi. Berbeda dengan arwahnya orang yang beriman, pintu-pintu langit dibukakan untuknya, sehingga arwahnya dapat naik ke langit yang ke tujuh, demikianlah menurut penjelasan hadis (dan tidak pula mereka masuk surga hingga unta masuk) yakni jika ada unta yang dapat masuk (ke dalam lubang jarum) maksudnya lubang yang ada pada jarum; ini kata kiasan bahwa hal itu tidak mungkin terjadi, demikian pula masuknya mereka ke dalam surga. (Demikianlah) pembalasan itu (Kami memberi balasan kepada orang-orang yang berbuat kejahatan) oleh sebab kekafirannya.",[["إِنَّ","Indeed"],["ٱلَّذِينَ","those who"],["كَذَّبُوا۟","denied"],["بِـَٔايَـٰتِنَا","Our Verses"],["وَٱسْتَكْبَرُوا۟","and (were) arrogant"],["عَنْهَا","towards them"],["لَا","(will) not"],["تُفَتَّحُ","be opened"],["لَهُمْ","for them"],["أَبْوَٰبُ","(the) doors"],["ٱلسَّمَآءِ","(of) the heaven"],["وَلَا","and not"],["يَدْخُلُونَ","they will enter"],["ٱلْجَنَّةَ","Paradise"],["حَتَّىٰ","until"],["يَلِجَ","passes"],["ٱلْجَمَلُ","the camel"],["فِى","through"],["سَمِّ","(the) eye"],["ٱلْخِيَاطِ ۚ","(of) the needle"],["وَكَذَٰلِكَ","And thus"],["نَجْزِى","We recompense"],["ٱلْمُجْرِمِينَ","the criminals"]]],"995":["(Mereka mempunyai tikar tidur dari api neraka) alas untuk tidur (dan di atas mereka ada selimut) penutup dari api neraka; ghawaasyin bentuk jamak dari kata ghaasyiyah, sedangkan tanwinnya adalah merupakan pergantian dari ya yang telah dibuang. (Demikianlah Kami memberi balasan kepada orang-orang yang zalim).",[["لَهُم","For them"],["مِّن","of"],["جَهَنَّمَ","(the) Hell"],["مِهَادٌۭ","(is) a bed"],["وَمِن","and from"],["فَوْقِهِمْ","over them"],["غَوَاشٍۢ ۚ","coverings"],["وَكَذَٰلِكَ","And thus"],["نَجْزِى","We recompense"],["ٱلظَّـٰلِمِينَ","the wrongdoers"]]],"996":["(Orang-orang yang beriman dan mengerjakan amal-amal saleh) menjadi mubtada, sedangkan firman Allah swt. (Kami tidak memikulkan kewajiban kepada diri seseorang melainkan sekedar kesanggupannya) sesuai kemampuannya dalam beramal; ini adalah jumlah mu'taridhah antara mubtada dan khabarnya, sedangkan khabarnya ialah (mereka itulah penghuni-penghuni surga, mereka kekal di dalamnya).",[["وَٱلَّذِينَ","But those who"],["ءَامَنُوا۟","believe"],["وَعَمِلُوا۟","and do"],["ٱلصَّـٰلِحَـٰتِ","[the] righteous deeds"],["لَا","not"],["نُكَلِّفُ","We burden"],["نَفْسًا","any soul"],["إِلَّا","except"],["وُسْعَهَآ","(to) its capacity"],["أُو۟لَـٰٓئِكَ","Those"],["أَصْحَـٰبُ","(are the) companions"],["ٱلْجَنَّةِ ۖ","(of) Paradise"],["هُمْ","they"],["فِيهَا","in it"],["خَـٰلِدُونَ","(will) abide forever"]]],"997":["(Dan Kami cabut segala macam dendam yang berada di dalam dada mereka) perasaan dengki yang pernah ada sewaktu mereka hidup di alam dunia (mengalir di bawah mereka) di bawah gedung-gedung tempat tinggal mereka (sungai-sungai dan mereka berkata,) tatkala mereka mulai menetap di tempat tinggal masing-masing (\"Segala puji bagi Allah yang telah menunjuki kami kepada surga ini) yakni amal perbuatan yang balasannya adalah hal ini (Dan kami sekali-kali tidak akan mendapat petunjuk kalau Allah tidak memberi kami petunjuk) di sini membuang jawabnya laula, hal itu bisa diketahui karena ada tanda sebelumnya yang menunjukkan kepadanya. (Sesungguhnya telah datang rasul-rasul Tuhan kami, membawa kebenaran.\" Dan diserukan kepada mereka bahwasanya) dengan anna yang ditakhfifkan, yakni annahuu. Atau dapat juga berasal dari an mufassirah (itulah surga yang diwariskan kepadamu, disebabkan apa yang dahulu kamu kerjakan).",[["وَنَزَعْنَا","And We will remove"],["مَا","whatever"],["فِى","(is) in"],["صُدُورِهِم","their breasts"],["مِّنْ","of"],["غِلٍّۢ","malice"],["تَجْرِى","Flows"],["مِن","from"],["تَحْتِهِمُ","underneath them"],["ٱلْأَنْهَـٰرُ ۖ","the rivers"],["وَقَالُوا۟","And they will say"],["ٱلْحَمْدُ","All the praise"],["لِلَّهِ","(is) for Allah"],["ٱلَّذِى","the One Who"],["هَدَىٰنَا","guided us"],["لِهَـٰذَا","to this"],["وَمَا","and not"],["كُنَّا","we were"],["لِنَهْتَدِىَ","to receive guidance"],["لَوْلَآ","if not"],["أَنْ","[that]"],["هَدَىٰنَا","(had) guided us"],["ٱللَّهُ ۖ","Allah"],["لَقَدْ","Certainly"],["جَآءَتْ","came"],["رُسُلُ","Messengers"],["رَبِّنَا","(of) our Lord"],["بِٱلْحَقِّ ۖ","with the truth"],["وَنُودُوٓا۟","And they will be addressed"],["أَن","[that]"],["تِلْكُمُ","This"],["ٱلْجَنَّةُ","(is) Paradise"],["أُورِثْتُمُوهَا","you have been made to inherit it"],["بِمَا","for what"],["كُنتُمْ","you used to"],["تَعْمَلُونَ","do"]]],"998":["(Dan penghuni-penghuni surga berseru kepada penghuni-penghuni neraka,) sebagai pernyataan dan ejekan (\"Sesungguhnya kami telah memperoleh apa yang telah Tuhan kami menjanjikannya kepada kami) berupa pahala (dengan sebenarnya. Maka apakah kamu telah memperoleh apa yang telah dijanjikan) kepadamu (oleh Tuhanmu) berupa azab (dengan sebenarnya?\" Mereka, penduduk neraka, menjawab, \"Betul.\" Kemudian seorang penyeru, malaikat, mengumumkan) menyerukan pengumuman (di antara mereka) yaitu di antara kedua golongan itu. Malaikat itu mengumandangkan kepada mereka (\"Kutukan Allah ditimpakan kepada orang-orang yang lalim).",[["وَنَادَىٰٓ","And will call out"],["أَصْحَـٰبُ","(the) companions"],["ٱلْجَنَّةِ","(of) Paradise"],["أَصْحَـٰبَ","(to the) companions"],["ٱلنَّارِ","(of) the Fire"],["أَن","that"],["قَدْ","Indeed"],["وَجَدْنَا","we found"],["مَا","what"],["وَعَدَنَا","(had) promised us"],["رَبُّنَا","our Lord"],["حَقًّۭا","true"],["فَهَلْ","So have"],["وَجَدتُّم","you found"],["مَّا","what"],["وَعَدَ","(was) promised"],["رَبُّكُمْ","(by) your Lord"],["حَقًّۭا ۖ","(to be) true"],["قَالُوا۟","They will say"],["نَعَمْ ۚ","Yes"],["فَأَذَّنَ","Then will announce"],["مُؤَذِّنٌۢ","an announcer"],["بَيْنَهُمْ","among them"],["أَن","[that]"],["لَّعْنَةُ","(The) curse"],["ٱللَّهِ","(of) Allah"],["عَلَى","(is) on"],["ٱلظَّـٰلِمِينَ","the wrongdoers"]]],"999":["(Yaitu orang-orang yang menghalangi) manusia (dari jalan Allah) dari tuntunan agama-Nya (dan menginginkan agar jalan itu) maksudnya mereka menghendaki agar jalan Allah itu (bengkok) tidak lurus (dan mereka ingkar terhadap kehidupan akhirat).",[["ٱلَّذِينَ","Those who"],["يَصُدُّونَ","hinder"],["عَن","from"],["سَبِيلِ","(the) way"],["ٱللَّهِ","(of) Allah"],["وَيَبْغُونَهَا","and seek in it"],["عِوَجًۭا","crookedness"],["وَهُم","while they (are)"],["بِٱلْـَٔاخِرَةِ","concerning the Hereafter"],["كَـٰفِرُونَ","disbelievers"]]],"1000":["(Dan di antara keduanya) yaitu antara para penghuni surga dan para penghuni neraka (ada batas) penghalang; menurut suatu pendapat batas itu berupa tembok vang diberi nama Al-A'raaf (di atas Al-A`raaf itu) yakni nama tembok surga (ada orang-orang) yang amat tampan dan amat buruk rupanya, rupa mereka sama, artinya yang cantik sama cantiknya dan yang buruk sama pula buruknya, sebagaimana yang dijelaskan oleh hadis (yang mengenal masing-masing dari kedua golongan itu) penduduk surga dan neraka (dengan tanda-tanda mereka) ciri-ciri khas mereka, yakni berbadan putih bagi orang-orang yang beriman dan berbadan hitam bagi orang-orang kafir, oleh sebab orang-orang yang di atas Al-A`raaf itu dapat langsung melihat kedua golongan itu mengingat mereka berada di tempat yang tinggi. (Dan mereka menyeru penduduk surga, 'Mudah-mudahan Allah melimpahkan kesejahteraan atas kamu.') Allah swt. berfirman, ('Mereka belum lagi memasukinya) yakni para penghuni Al-A'raaf itu ke surga (sedangkan mereka ingin segera')\" memasukinya. Hasan mengatakan, \"Mereka tidak terdorong oleh rasa keinginan yang sangat melainkan karena memang Allah telah menghendakinya untuk mereka.\" Dan Imam Hakim telah meriwayatkan dari Hudzaifah yang telah mengatakan, \"Tatkala calon penghuni surga itu dalam keadaan demikian berada di Al-A'raaf, kemudian Tuhanmu muncul di hadapan mereka seraya berfirman, 'Masuklah kamu sekalian ke dalam surga, sesungguhnya Aku telah mengampuni kamu.'\"",[["وَبَيْنَهُمَا","And between them"],["حِجَابٌۭ ۚ","(will be) a partition"],["وَعَلَى","and on"],["ٱلْأَعْرَافِ","the heights"],["رِجَالٌۭ","(will be) men"],["يَعْرِفُونَ","recognizing"],["كُلًّۢا","all"],["بِسِيمَىٰهُمْ ۚ","by their marks"],["وَنَادَوْا۟","And they will call out"],["أَصْحَـٰبَ","(to the) companions"],["ٱلْجَنَّةِ","(of) Paradise"],["أَن","that"],["سَلَـٰمٌ","Peace"],["عَلَيْكُمْ ۚ","(be) upon you"],["لَمْ","Not"],["يَدْخُلُوهَا","they have entered it"],["وَهُمْ","but they"],["يَطْمَعُونَ","hope"]]],"1001":["(Dan apabila pandangan mereka dialihkan) yakni Ashhaabul A`raaf itu (ke arah) ke sebelah (penghuni neraka, mereka berkata, \"Ya Tuhan kami! Janganlah Engkau tempatkan kami) di dalam neraka (bersama-sama orang-orang yang lalim itu\").",[["۞ وَإِذَا","And when"],["صُرِفَتْ","are turned"],["أَبْصَـٰرُهُمْ","their eyes"],["تِلْقَآءَ","towards"],["أَصْحَـٰبِ","(the) companions"],["ٱلنَّارِ","(of) the Fire"],["قَالُوا۟","they (will) say"],["رَبَّنَا","Our Lord"],["لَا","(Do) not"],["تَجْعَلْنَا","place us"],["مَعَ","with"],["ٱلْقَوْمِ","the people "],["ٱلظَّـٰلِمِينَ","the wrongdoers"]]],"1002":["(Dan orang-orang yang di atas Al-A`raaf memanggil beberapa orang pemuka-pemuka) penduduk neraka (yang mereka mengenalnya dengan tanda-tandanya dengan mengatakan, \"Tidaklah memberi manfaat kepadamu) dapat menyelamatkanmu dari neraka (apa yang kamu kumpulkan) yakni harta benda atau banyaknya bilangan kamu (dan apa yang selalu kamu sombongkan itu.\") yaitu kepongahanmu tidak mau beriman, kemudian orang-orang yang di atas Al-A`raaf bertanya kepada penghuni neraka seraya memberi isyarat kepada orang-orang Islam yang lemah.",[["وَنَادَىٰٓ","And (will) call out"],["أَصْحَـٰبُ","(the) companions"],["ٱلْأَعْرَافِ","(of) the heights"],["رِجَالًۭا","(to) men"],["يَعْرِفُونَهُم","whom they recognize"],["بِسِيمَىٰهُمْ","by their marks"],["قَالُوا۟","saying"],["مَآ","Not"],["أَغْنَىٰ","(has) availed"],["عَنكُمْ","[to] you"],["جَمْعُكُمْ","your gathering"],["وَمَا","and what"],["كُنتُمْ","you were"],["تَسْتَكْبِرُونَ","arrogant (about)"]]],"1003":["(\"Itukah orang-orang yang telah kamu bersumpah bahwa mereka tidak akan mendapat rahmat Allah?\") akan tetapi telah dikatakan kepada orang-orang Islam yang lemah itu (\"Masuklah ke dalam surga, tidak ada kekhawatiran terhadapmu dan tidak pula kamu bersedih hati\") menurut suatu qiraat dibaca dengan bina maf'ul yakni udkhiluu dan dukhiluu, jumlah nafi menjadi hal yakni perkataan tersebut ditujukan kepada mereka.",[["أَهَـٰٓؤُلَآءِ","Are these"],["ٱلَّذِينَ","the ones whom"],["أَقْسَمْتُمْ","you had sworn"],["لَا","(that) not"],["يَنَالُهُمُ","(will) grant them"],["ٱللَّهُ","Allah"],["بِرَحْمَةٍ ۚ","Mercy"],["ٱدْخُلُوا۟","Enter"],["ٱلْجَنَّةَ","Paradise"],["لَا","(There will be) no"],["خَوْفٌ","fear"],["عَلَيْكُمْ","upon you"],["وَلَآ","and not"],["أَنتُمْ","you"],["تَحْزَنُونَ","will grieve"]]],"1004":["(Dan penghuni neraka menyeru kepada penghuni surga, \"Limpahkanlah kepada kami sedikit air atau apa yang telah direzekikan Allah kepadamu.\") yaitu makanan (Mereka, para penghuni surga, menjawab, \"Sesungguhnya Allah telah mengharamkan keduanya) telah melarang makanan dan minuman itu (atas orang-orang kafir).",[["وَنَادَىٰٓ","And (will) call out"],["أَصْحَـٰبُ","(the) companions"],["ٱلنَّارِ","(of) the Fire"],["أَصْحَـٰبَ","(to the) companions"],["ٱلْجَنَّةِ","(of) Paradise"],["أَنْ","[that]"],["أَفِيضُوا۟","Pour"],["عَلَيْنَا","upon us"],["مِنَ","[of]"],["ٱلْمَآءِ","(some) water"],["أَوْ","or"],["مِمَّا","of what"],["رَزَقَكُمُ","(has been) provided (to) you"],["ٱللَّهُ ۚ","(by) Allah"],["قَالُوٓا۟","They (will) say"],["إِنَّ","Indeed"],["ٱللَّهَ","Allah"],["حَرَّمَهُمَا","has forbidden both"],["عَلَى","to"],["ٱلْكَـٰفِرِينَ","the disbelievers"]]],"1005":["(Yaitu orang-orang yang menjadikan agama mereka sebagai main-mainan dan senda-gurau, dan kehidupan dunia telah menipu mereka.\" Maka pada hari ini, hari kiamat, Kami melupakan mereka) Kami membiarkan mereka di dalam neraka (sebagaimana mereka melupakan pertemuan mereka dengan hari ini) di mana mereka mengabaikan beramal baik untuk menghadapinya (dan sebagaimana mereka selalu mengingkari ayat-ayat Kami) sebagaimana mereka telah berlaku ingkar terhadapnya.",[["ٱلَّذِينَ","Those who"],["ٱتَّخَذُوا۟","took"],["دِينَهُمْ","their religion"],["لَهْوًۭا","(as) an amusement"],["وَلَعِبًۭا","and play"],["وَغَرَّتْهُمُ","and deluded them"],["ٱلْحَيَوٰةُ","the life"],["ٱلدُّنْيَا ۚ","(of) the world"],["فَٱلْيَوْمَ","So today"],["نَنسَىٰهُمْ","We forget them"],["كَمَا","as"],["نَسُوا۟","they forgot"],["لِقَآءَ","(the) meeting"],["يَوْمِهِمْ","(of) their day"],["هَـٰذَا","this"],["وَمَا","and [what]"],["كَانُوا۟","(as) they used to"],["بِـَٔايَـٰتِنَا","with Our Verses"],["يَجْحَدُونَ","they reject"]]],"1006":["(Dan sesungguhnya Kami telah mendatangkan kepada mereka) para penduduk Mekah (sebuah Kitab) yakni Alquran (yang Kami telah menjelaskannya) telah Kami terangkan melalui berita-beritanya, janji-janjinya dan ancaman-ancamannya (atas dasar pengetahuan Kami) menjadi hal, yakni Kami mengetahui tentang apa yang terincikan di dalamnya (menjadi petunjuk) menjadi hal bagi dhamir ha (dan rahmat bagi orang-orang yang beriman) kepadanya.",[["وَلَقَدْ","And certainly"],["جِئْنَـٰهُم","We had brought them"],["بِكِتَـٰبٍۢ","a Book"],["فَصَّلْنَـٰهُ","which We have explained"],["عَلَىٰ","with"],["عِلْمٍ","knowledge "],["هُدًۭى","as guidance"],["وَرَحْمَةًۭ","and mercy"],["لِّقَوْمٍۢ","for a people"],["يُؤْمِنُونَ","who believe"]]],"1007":["(Tiadalah mereka menunggu-nunggu) mereka tidak menunggu (kecuali terlaksananya kebenaran Alquran itu) akibat dari apa yang ada di dalamnya. (Pada hari datangnya kebenaran pemberitaan Alquran itu) yaitu hari kiamat (berkatalah orang-orang yang melupakannya sebelum itu,) mereka tidak mau beriman kepada Alquran (\"Sesungguhnya telah datang rasul-rasul Tuhan kami membawa yang hak, maka adakah bagi kami pemberi syafaat yang akan memberi syafaat kepada kami atau) dapatkah (kami dikembalikan) ke dunia (sehingga dapat beramal yang lain dari yang pernah kami amalkan?\") kami akan mentauhidkan Allah dan meninggalkan kemusyrikan. Kemudian dikatakan kepada mereka, \"Tidak dapat.\" Allah swt. berfirman, (Sungguh mereka telah merugikan diri mereka sendiri) sebab mereka menjadi binasa (dan lenyaplah) maksudnya hilanglah (dari mereka tuhan-tuhan yang mereka ada-adakan) sebagai sekutu Allah yang mereka buat-buat sendiri.",[["هَلْ","Do"],["يَنظُرُونَ","they wait"],["إِلَّا","except"],["تَأْوِيلَهُۥ ۚ","(for) its fulfillment"],["يَوْمَ","(The) Day"],["يَأْتِى","(will) come"],["تَأْوِيلُهُۥ","its fulfillment"],["يَقُولُ","will say"],["ٱلَّذِينَ","those who"],["نَسُوهُ","had forgotten it"],["مِن","from"],["قَبْلُ","before"],["قَدْ","Verily"],["جَآءَتْ","had come"],["رُسُلُ","(the) Messengers"],["رَبِّنَا","(of) our Lord"],["بِٱلْحَقِّ","with the truth"],["فَهَل","so are (there)"],["لَّنَا","for us"],["مِن","any"],["شُفَعَآءَ","intercessors"],["فَيَشْفَعُوا۟","so (that) they intercede"],["لَنَآ","for us"],["أَوْ","or"],["نُرَدُّ","we are sent back"],["فَنَعْمَلَ","so (that) we do (deeds)"],["غَيْرَ","other than"],["ٱلَّذِى","that which"],["كُنَّا","we used to"],["نَعْمَلُ ۚ","do"],["قَدْ","Verily"],["خَسِرُوٓا۟","they lost"],["أَنفُسَهُمْ","themselves"],["وَضَلَّ","and strayed"],["عَنْهُم","from them"],["مَّا","what"],["كَانُوا۟","they used to"],["يَفْتَرُونَ","invent"]]],"1008":["(Sesungguhnya Tuhan kamu ialah Allah yang telah menciptakan langit dan bumi dalam enam masa) menurut ukuran hari dunia atau yang sepadan dengannya, sebab pada zaman itu masih belum ada matahari. Akan tetapi jika Allah menghendakinya niscaya Ia dapat menciptakannya dalam sekejap mata, adapun penyebutan hal ini dimaksud guna mengajari makhluk-Nya agar tekun dan sabar dalam mengerjakan sesuatu (lalu Dia bersemayam di atas Arsy) Arsy menurut istilah bahasa artinya singgasana raja, yang dimaksud dengan bersemayam ialah yang sesuai dengan kebesaran Allah dan kesucian-Nya (Dia menutupkan malam kepada siang) bisa dibaca takhfif yakni yughsyii dan dibaca tasydid, yakni yughasysyii, artinya: keduanya itu saling menutupi yang lain silih-berganti (yang mengikutinya) masing-masing di antara keduanya itu mengikuti yang lainnya (dengan cepat) secara cepat (dan diciptakan-Nya pula matahari, bulan dan bintang-bintang) dengan dibaca nashab diathafkan kepada as-samaawaat, dan dibaca rafa` sebagai mubtada sedangkan khabarnya ialah (masing-masing tunduk) patuh (kepada perintah-Nya) kepada kekuasaan-Nya (ingatlah, menciptakan itu hanya hak Allah) semuanya (dan memerintah) kesemuanya adalah hak-Nya pula (Maha Suci) Maha Besar (Allah, Tuhan) Pemelihara (semesta alam).",[["إِنَّ","Indeed"],["رَبَّكُمُ","your Lord"],["ٱللَّهُ","(is) Allah"],["ٱلَّذِى","the One Who"],["خَلَقَ","created"],["ٱلسَّمَـٰوَٰتِ","the heavens"],["وَٱلْأَرْضَ","and the earth"],["فِى","in"],["سِتَّةِ","six"],["أَيَّامٍۢ","epochs"],["ثُمَّ","then"],["ٱسْتَوَىٰ","He ascended"],["عَلَى","on"],["ٱلْعَرْشِ","the Throne"],["يُغْشِى","He covers"],["ٱلَّيْلَ","the night"],["ٱلنَّهَارَ","(with) the day"],["يَطْلُبُهُۥ","seeking it"],["حَثِيثًۭا","rapidly"],["وَٱلشَّمْسَ","and the sun"],["وَٱلْقَمَرَ","and the moon"],["وَٱلنُّجُومَ","and the stars "],["مُسَخَّرَٰتٍۭ","subjected"],["بِأَمْرِهِۦٓ ۗ","by His command"],["أَلَا","Unquestionably"],["لَهُ","for Him"],["ٱلْخَلْقُ","(is) the creation"],["وَٱلْأَمْرُ ۗ","and the command"],["تَبَارَكَ","blessed"],["ٱللَّهُ","(is) Allah"],["رَبُّ","Lord"],["ٱلْعَـٰلَمِينَ","(of) the worlds"]]],"1009":["(Berdoalah kepada Tuhanmu dengan berendah diri) menjadi hal, yakni merendahkan diri (dan dengan suara yang lembut) secara berbisik-bisik (Sesungguhnya Allah tidak menyukai orang-orang yang melampaui batas) di dalam berdoa. Seperti banyak berbicara dengan suara yang keras.",[["ٱدْعُوا۟","Call upon"],["رَبَّكُمْ","your Lord"],["تَضَرُّعًۭا","humbly"],["وَخُفْيَةً ۚ","and privately"],["إِنَّهُۥ","Indeed, He"],["لَا","(does) not"],["يُحِبُّ","love"],["ٱلْمُعْتَدِينَ","the transgressors"]]],"1010":["(Dan janganlah kamu membuat kerusakan di muka bumi) dengan melakukan kemusyrikan dan perbuatan-perbuatan maksiat (sesudah Allah memperbaikinya) dengan cara mengutus rasul-rasul (dan berdoalah kepada-Nya dengan rasa takut) terhadap siksaan-Nya (dan dengan penuh harap) terhadap rahmat-Nya. (Sesungguhnya rahmat Allah amat dekat kepada orang-orang yang berbuat baik) yakni orang-orang yang taat. Lafal qariib berbentuk mudzakkar padahal menjadi khabar lafal rahmah yang muannats, hal ini karena lafal rahmah dimudhafkan kepada lafal Allah.",[["وَلَا","And (do) not"],["تُفْسِدُوا۟","cause corruption"],["فِى","in"],["ٱلْأَرْضِ","the earth"],["بَعْدَ","after"],["إِصْلَـٰحِهَا","its reformation"],["وَٱدْعُوهُ","And call Him"],["خَوْفًۭا","(in) fear"],["وَطَمَعًا ۚ","and hope"],["إِنَّ","Indeed"],["رَحْمَتَ","(the) Mercy"],["ٱللَّهِ","(of) Allah"],["قَرِيبٌۭ","(is) near"],["مِّنَ","for"],["ٱلْمُحْسِنِينَ","the good-doers"]]],"1011":["(Dan Dialah yang meniupkan angin sebagai pembawa berita gembira sebelum kedatangan rahmat-Nya) yakni terpencar-pencar sebelum datangnya hujan. Menurut suatu qiraat dibaca dengan takhfif, yaitu syin disukunkan; dan menurut qiraat lainnya dengan disukunkan syinnya kemudian memakai nun yang difatahkan sebagai mashdar. Menurut qiraat lainnya lagi dengan disukunkan syinnya kemudian didamahkan huruf sebelumnya sebagai pengganti dari nun, yakni mubsyiran. Bentuk tunggal (dari yang pertama ialah nusyuurun seperti lafal rasuulun, sedangkan bentuk tunggal yang kedua ialah basyiirun (sehingga apabila angin itu membawa) maksudnya meniupkan (mendung yang tebal) yaitu hujan (Kami halau mendung itu) mega yang mengandung air hujan itu. Di dalam lafal ini terkandung makna iltifat `anil ghaibiyyah (ke suatu daerah yang tandus) daerah yang tidak ada tetumbuhannya guna menyuburkannya (lalu Kami turunkan di daerah itu) di kawasan tersebut (hujan, maka Kami keluarkan dengan sebab hujan itu berbagai macam buah-buahan. Seperti itulah) cara pengeluaran itulah (Kami membangkitkan orang-orang yang telah mati) dari kuburan mereka dengan menghidupkan mereka kembali (mudah-mudahan kamu mengambil pelajaran) kemudian kamu mau beriman.",[["وَهُوَ","And He"],["ٱلَّذِى","(is) the One Who"],["يُرْسِلُ","sends"],["ٱلرِّيَـٰحَ","the winds"],["بُشْرًۢا","(as) glad tidings"],["بَيْنَ","from"],["يَدَىْ","before"],["رَحْمَتِهِۦ ۖ","His Mercy"],["حَتَّىٰٓ","until"],["إِذَآ","when"],["أَقَلَّتْ","they have carried"],["سَحَابًۭا","clouds "],["ثِقَالًۭا","heavy"],["سُقْنَـٰهُ","We drive them"],["لِبَلَدٍۢ","to a land"],["مَّيِّتٍۢ","dead"],["فَأَنزَلْنَا","then We send down"],["بِهِ","from it"],["ٱلْمَآءَ","the water"],["فَأَخْرَجْنَا","then We bring forth"],["بِهِۦ","from it"],["مِن","(of)"],["كُلِّ","all (kinds)"],["ٱلثَّمَرَٰتِ ۚ","(of) fruits"],["كَذَٰلِكَ","Thus"],["نُخْرِجُ","We will bring forth"],["ٱلْمَوْتَىٰ","the dead"],["لَعَلَّكُمْ","so that you may"],["تَذَكَّرُونَ","take heed"]]],"1012":["(Dan tanah yang baik) yang subur tanahnya (tanaman-tanamannya tumbuh subur) tumbuh dengan baik (dengan seizin Tuhannya) hal ini merupakan perumpamaan bagi orang mukmin yang mau mendengar petuah/nasihat kemudian ia mengambil manfaat dari nasihat itu (dan tanah yang tidak subur) jelek tanahnya (tidaklah mengeluarkan) tanamannya (kecuali tumbuh merana) sulit dan susah tumbuhnya. Hal ini merupakan perumpamaan bagi orang yang kafir. (Demikianlah) seperti apa yang telah Kami jelaskan (Kami menjelaskan) menerangkan (ayat-ayat Kami kepada orang-orang yang bersyukur) terhadap Allah, kemudian mereka mau beriman kepada-Nya.",[["وَٱلْبَلَدُ","And the land "],["ٱلطَّيِّبُ","[the] pure"],["يَخْرُجُ","comes forth"],["نَبَاتُهُۥ","its vegetation"],["بِإِذْنِ","by (the) permission"],["رَبِّهِۦ ۖ","(of) its Lord"],["وَٱلَّذِى","but which"],["خَبُثَ","is bad "],["لَا","(does) not"],["يَخْرُجُ","come forth"],["إِلَّا","except"],["نَكِدًۭا ۚ","(with) difficulty"],["كَذَٰلِكَ","Thus"],["نُصَرِّفُ","We explain"],["ٱلْـَٔايَـٰتِ","the Signs"],["لِقَوْمٍۢ","for a people"],["يَشْكُرُونَ","who are grateful"]]],"1013":["(Sesungguhnya) merupakan jawab dari qasam/sumpah yang mahdzuf/tidak disebutkan. (Kami telah mengutus Nuh kepada kaumnya lalu ia berkata, \"Wahai kaumku, sembahlah Allah, sekali-kali tak ada Tuhan bagimu selain-Nya.\") dengan dibaca jar sebagai sifat dari lafal ilaahun, dan dibaca rafa' sebagai badal dari lafal ilaahun (Sesungguhnya aku takut kamu) jika kamu menyembah selain Allah (akan ditimpa azab yang besar) yakni azab pada hari kiamat.",[["لَقَدْ","Certainly"],["أَرْسَلْنَا","We sent"],["نُوحًا","Nuh"],["إِلَىٰ","to"],["قَوْمِهِۦ","his people"],["فَقَالَ","and he said"],["يَـٰقَوْمِ","O my people"],["ٱعْبُدُوا۟","Worship"],["ٱللَّهَ","Allah"],["مَا","not"],["لَكُم","for you"],["مِّنْ","any"],["إِلَـٰهٍ","god"],["غَيْرُهُۥٓ","other than Him"],["إِنِّىٓ","Indeed, I"],["أَخَافُ","[I] fear"],["عَلَيْكُمْ","for you"],["عَذَابَ","punishment"],["يَوْمٍ","(of the) Day"],["عَظِيمٍۢ","Great"]]],"1014":["(Pemuka-pemuka) orang-orang terhormat (dari kaumnya berkata, \"Sesungguhnya kami memandang kamu berada dalam kesesatan yang nyata.\") yang jelas.",[["قَالَ","Said"],["ٱلْمَلَأُ","the chiefs"],["مِن","of"],["قَوْمِهِۦٓ","his people"],["إِنَّا","Indeed, we"],["لَنَرَىٰكَ","surely see you"],["فِى","in"],["ضَلَـٰلٍۢ","error"],["مُّبِينٍۢ","clear"]]],"1015":["(Nuh menjawab, \"Hai kaumku, tak ada padaku kesesatan sedikit pun) lafal dhalaalah lebih umum pengertiannya daripada lafal adh-dhalaal dengan demikian maka penolakannya pun lebih kuat (tetapi aku adalah utusan dari Tuhan semesta alam.\")",[["قَالَ","He said"],["يَـٰقَوْمِ","O my people"],["لَيْسَ","There is not"],["بِى","in me"],["ضَلَـٰلَةٌۭ","error"],["وَلَـٰكِنِّى","but I am"],["رَسُولٌۭ","a Messenger"],["مِّن","from"],["رَّبِّ","(the) Lord"],["ٱلْعَـٰلَمِينَ","(of) the worlds"]]],"1016":["(\"Aku sampaikan kepadamu) dengan dibaca takhfif dan tasydid (amanat-amanat Tuhanku dan aku memberi nasihat) maksudnya, aku menghendaki kebaikan (kepadamu, dan aku mengetahui dari Allah apa yang tidak kamu ketahui.\")",[["أُبَلِّغُكُمْ","I convey to you"],["رِسَـٰلَـٰتِ","the Messages"],["رَبِّى","(of) my Lord"],["وَأَنصَحُ","and [I] advise"],["لَكُمْ","[to] you"],["وَأَعْلَمُ","and I know"],["مِنَ","from"],["ٱللَّهِ","Allah"],["مَا","what"],["لَا","not"],["تَعْلَمُونَ","you know"]]],"1017":["(Apakah) kamu tidak percaya (dan heran bahwa datang kepada kamu peringatan) yakni pelajaran (dari Tuhanmu dengan perantaraan) lisan (seorang laki-laki dari golonganmu agar dia memberi peringatan kepadamu) tentang siksaan jika kamu tidak mau beriman (dan mudah-mudahan kamu bertakwa) kepada Allah (dan supaya kamu mendapat rahmat?) oleh sebab pelajaran itu.",[["أَوَعَجِبْتُمْ","Do you wonder"],["أَن","that"],["جَآءَكُمْ","has come to you"],["ذِكْرٌۭ","a reminder"],["مِّن","from"],["رَّبِّكُمْ","your Lord"],["عَلَىٰ","on"],["رَجُلٍۢ","a man"],["مِّنكُمْ","among you"],["لِيُنذِرَكُمْ","that he may warn you"],["وَلِتَتَّقُوا۟","and that you may fear"],["وَلَعَلَّكُمْ","and so that you may"],["تُرْحَمُونَ","receive mercy"]]],"1018":["(Maka mereka mendustakan Nuh, kemudian Kami selamatkan dia dan orang-orang yang bersamanya) dari tenggelam (di dalam bahtera) perahu (dan Kami tenggelamkan orang-orang yang mendustakan ayat-ayat Kami) dengan banjir besar. (Sesungguhnya mereka adalah kaum yang buta) mata hatinya dari kebenaran.",[["فَكَذَّبُوهُ","But they denied him"],["فَأَنجَيْنَـٰهُ","so We saved him"],["وَٱلَّذِينَ","and those who"],["مَعَهُۥ","(were) with him"],["فِى","in"],["ٱلْفُلْكِ","the ship"],["وَأَغْرَقْنَا","And We drowned"],["ٱلَّذِينَ","those who"],["كَذَّبُوا۟","denied"],["بِـَٔايَـٰتِنَآ ۚ","Our Verses"],["إِنَّهُمْ","Indeed, they"],["كَانُوا۟","were"],["قَوْمًا","a people"],["عَمِينَ","blind"]]],"1019":["(Dan) Kami telah mengutus (kepada kaum Ad) yang pertama (saudara mereka yaitu Hud. Ia berkata, \"Hai kaumku, sembahlah Allah) tauhidkanlah Allah (sekali-kali tidak ada Tuhan bagimu selain dari-Nya. Maka mengapa kamu tidak bertakwa?\") kamu tidak takut kepada-Nya sehingga kamu mau mengimani-Nya.",[["۞ وَإِلَىٰ","And to"],["عَادٍ","Aad"],["أَخَاهُمْ","(We sent) their brother"],["هُودًۭا ۗ","Hud"],["قَالَ","He said"],["يَـٰقَوْمِ","O my people"],["ٱعْبُدُوا۟","Worship"],["ٱللَّهَ","Allah"],["مَا","not"],["لَكُم","for you"],["مِّنْ","any"],["إِلَـٰهٍ","god"],["غَيْرُهُۥٓ ۚ","other than Him"],["أَفَلَا","Then will not"],["تَتَّقُونَ","you fear (Allah)"]]],"1020":["(Pemuka-pemuka yang kafir dari kaumnya berkata, \"Sesungguhnya kami benar-benar memandang kamu dalam keadaan kurang akal) yaitu bodoh (dan sesungguhnya kami menganggap kamu termasuk orang-orang yang berdusta.\") di dalam kerasulanmu.",[["قَالَ","Said"],["ٱلْمَلَأُ","the chiefs"],["ٱلَّذِينَ","(of) those who"],["كَفَرُوا۟","disbelieved"],["مِن","from"],["قَوْمِهِۦٓ","his people"],["إِنَّا","Indeed, we"],["لَنَرَىٰكَ","surely, see you"],["فِى","in"],["سَفَاهَةٍۢ","foolishness"],["وَإِنَّا","and indeed, we"],["لَنَظُنُّكَ","[we] think you"],["مِنَ","(are) of"],["ٱلْكَـٰذِبِينَ","the liars"]]],"1021":["(Hud berkata, \"Hai kaumku! Tidak ada padaku kekurangan akal sedikit pun tetapi aku ini adalah utusan dari Tuhan semesta alam)",[["قَالَ","He said"],["يَـٰقَوْمِ","O my people"],["لَيْسَ","There is not"],["بِى","in me"],["سَفَاهَةٌۭ","foolishness"],["وَلَـٰكِنِّى","but I am"],["رَسُولٌۭ","a Messenger"],["مِّن","from"],["رَّبِّ","(the) Lord"],["ٱلْعَـٰلَمِينَ","(of) the worlds"]]],"1022":["(Aku menyampaikan amanat-amanah Tuhanku kepadamu dan aku hanyalah pemberi nasihat yang terpercaya bagimu\") yakni orang yang dipercaya untuk mengemban risalah.",[["أُبَلِّغُكُمْ","I convey to you"],["رِسَـٰلَـٰتِ","Messages"],["رَبِّى","(of) my Lord"],["وَأَنَا۠","and I am"],["لَكُمْ","to you"],["نَاصِحٌ","an adviser "],["أَمِينٌ","trustworthy"]]],"1023":["(Apakah kamu tidak percaya dan heran bahwa datang kepadamu peringatan dari Tuhanmu yang dibawa oleh) lisan (seorang laki-laki di antara kamu untuk memberi peringatan kepadamu? Dan ingatlah oleh kamu sekalian di waktu Allah menjadikan kamu sebagai pengganti-pengganti yang berkuasa) di muka bumi (sesudah lenyapnya kaum Nuh dan Tuhan telah melebihkan kekuatan tubuh dan perawakanmu) memberi kekuatan dan tinggi tubuh; tersebutlah bahwa orang yang paling tinggi di antara mereka adalah seratus hasta, sedangkan yang paling pendek enam puluh hasta (Maka ingatlah nikmat-nikmat Allah) yaitu karunia-karunia-Nya (supaya kamu mendapat keberuntungan) supaya kamu memperoleh keberhasilan.",[["أَوَعَجِبْتُمْ","Do you wonder"],["أَن","that"],["جَآءَكُمْ","has come to you"],["ذِكْرٌۭ","a reminder"],["مِّن","from"],["رَّبِّكُمْ","your Lord"],["عَلَىٰ","on"],["رَجُلٍۢ","a man"],["مِّنكُمْ","among you"],["لِيُنذِرَكُمْ ۚ","that he may warn you"],["وَٱذْكُرُوٓا۟","And remember"],["إِذْ","when"],["جَعَلَكُمْ","He made you"],["خُلَفَآءَ","successors"],["مِنۢ","from"],["بَعْدِ","after"],["قَوْمِ","(the) people"],["نُوحٍۢ","(of) Nuh"],["وَزَادَكُمْ","and increased you"],["فِى","in"],["ٱلْخَلْقِ","the stature"],["بَصْۜطَةًۭ ۖ","extensively"],["فَٱذْكُرُوٓا۟","So remember"],["ءَالَآءَ","(the) Bounties"],["ٱللَّهِ","(of) Allah"],["لَعَلَّكُمْ","so that you may"],["تُفْلِحُونَ","succeed"]]],"1024":["(Mereka berkata, \"Apakah kamu datang kepada kami agar kami hanya menyembah Allah saja dan meninggalkan) artinya membiarkan (apa yang biasa disembah oleh bapak-bapak kami? Maka datangkanlah apa yang kamu ancamkan kepada kami) berupa azab (jika kamu termasuk orang-orang yang benar\") di dalam pengakuanmu.",[["قَالُوٓا۟","They said"],["أَجِئْتَنَا","Have you come to us"],["لِنَعْبُدَ","that we (should) worship"],["ٱللَّهَ","Allah"],["وَحْدَهُۥ","Alone"],["وَنَذَرَ","and we forsake"],["مَا","what"],["كَانَ","used to"],["يَعْبُدُ","worship"],["ءَابَآؤُنَا ۖ","our forefathers"],["فَأْتِنَا","Then bring us"],["بِمَا","of what"],["تَعِدُنَآ","you promise us"],["إِن","if"],["كُنتَ","you are"],["مِنَ","of"],["ٱلصَّـٰدِقِينَ","the truthful"]]],"1025":["(Ia berkata, \"Sungguh sudah pasti) telah wajib (kamu akan ditimpa azab Tuhanmu) yakni siksaan-Nya (dan kemarahan-Nya. Apakah kamu sekalian hendak berbantah dengan aku tentang nama-nama yang telah kamu menamakannya) artinya yang telah diberi nama oleh kamu (kamu beserta nenek-moyangmu) yang dimaksud ialah berhala-berhala yang biasa mereka sembah (padahal Allah sekali-kali tidak menurunkan untuk itu) untuk menyembahnya (suatu hujah pun?) bukti argumentasi. (Maka tunggulah olehmu) azab itu (sesungguhnya aku juga termasuk orang-orang yang menunggu bersama kamu.\") menanti azab itu disebabkan kedustaanmu kepadaku. Kemudian dikirimkan kepada mereka angin yang panas sekali. Maksudnya, Allah menimpakan azab-Nya atas mereka dengan angin yang amat panas.",[["قَالَ","He said"],["قَدْ","Verily"],["وَقَعَ","has fallen"],["عَلَيْكُم","upon you"],["مِّن","from"],["رَّبِّكُمْ","your Lord"],["رِجْسٌۭ","punishment"],["وَغَضَبٌ ۖ","and anger"],["أَتُجَـٰدِلُونَنِى","Do you dispute with me"],["فِىٓ","concerning"],["أَسْمَآءٍۢ","names"],["سَمَّيْتُمُوهَآ","you have named them "],["أَنتُمْ","you"],["وَءَابَآؤُكُم","and your forefathers"],["مَّا","Not"],["نَزَّلَ","(has been) sent down"],["ٱللَّهُ","(by) Allah"],["بِهَا","for it"],["مِن","any"],["سُلْطَـٰنٍۢ ۚ","authority"],["فَٱنتَظِرُوٓا۟","Then wait"],["إِنِّى","indeed, I am"],["مَعَكُم","with you"],["مِّنَ","of"],["ٱلْمُنتَظِرِينَ","the ones who wait"]]],"1026":["(Maka Kami selamatkan dia) Hud (beserta orang-orang yang bersamanya) dari kalangan orang-orang yang beriman (dengan rahmat yang besar dari Kami dan Kami tumpas) kaumnya itu (orang-orang yang mendustakan ayat-ayat Kami) Kami habiskan mereka dengan akar-akarnya (dan tiadalah mereka orang-orang yang beriman) diathafkan kepada lafal kadzdzabuu.",[["فَأَنجَيْنَـٰهُ","So We saved him"],["وَٱلَّذِينَ","and those"],["مَعَهُۥ","with him"],["بِرَحْمَةٍۢ","by Mercy"],["مِّنَّا","from Us"],["وَقَطَعْنَا","And We cut off"],["دَابِرَ","the roots"],["ٱلَّذِينَ","(of) those who"],["كَذَّبُوا۟","denied"],["بِـَٔايَـٰتِنَا ۖ","Our Signs"],["وَمَا","and not"],["كَانُوا۟","they were"],["مُؤْمِنِينَ","believers"]]],"1027":["(Dan) Kami telah mengutus (kepada kaum Tsamud) tanpa tanwin, yang dimaksud adalah kabilahnya (saudara mereka Saleh. Ia berkata, \"Hai kaumku, sembahlah Allah sekali-kali tidak ada Tuhan bagimu selain-Nya. Sesungguhnya telah datang bukti yang nyata) yakni mukjizat (dari Tuhanmu) yang membenarkan kerasulanku. (Unta betina ini menjadi tanda bagimu) menjadi hal sedangkan amilnya adalah makna yang terkandung dalam isyarah. Sebelumnya kaum Nabi Saleh itu meminta kepadanya agar ia mengeluarkan unta betina tersebut dari sebuah batu besar yang telah mereka tentukan sendiri (maka biarkanlah dia makan di bumi Allah dan janganlah kamu mengganggunya dengan gangguan apa pun) menyembelihnya atau memukulnya (maka kamu ditimpa siksaan yang pedih.\").",[["وَإِلَىٰ","And to"],["ثَمُودَ","Thamud"],["أَخَاهُمْ","(We sent) their brother"],["صَـٰلِحًۭا ۗ","Salih"],["قَالَ","He said"],["يَـٰقَوْمِ","O my people"],["ٱعْبُدُوا۟","Worship"],["ٱللَّهَ","Allah"],["مَا","not"],["لَكُم","for you"],["مِّنْ","any"],["إِلَـٰهٍ","god"],["غَيْرُهُۥ ۖ","other than Him"],["قَدْ","Verily"],["جَآءَتْكُم","has come to you"],["بَيِّنَةٌۭ","a clear proof"],["مِّن","from"],["رَّبِّكُمْ ۖ","your Lord"],["هَـٰذِهِۦ","This"],["نَاقَةُ","(is) a she-camel"],["ٱللَّهِ","(of) Allah"],["لَكُمْ","(it is) for you"],["ءَايَةًۭ ۖ","a Sign"],["فَذَرُوهَا","So you leave her"],["تَأْكُلْ","(to) eat"],["فِىٓ","on"],["أَرْضِ","(the) earth"],["ٱللَّهِ ۖ","(of) Allah"],["وَلَا","and (do) not"],["تَمَسُّوهَا","touch her"],["بِسُوٓءٍۢ","with harm"],["فَيَأْخُذَكُمْ","lest seizes you"],["عَذَابٌ","a punishment"],["أَلِيمٌۭ","painful"]]],"1028":["(Dan ingatlah olehmu di waktu Tuhan menjadikan kamu pengganti-pengganti) di bumi ini (sesudah kaum Ad dan memberikan tempat bagimu) yakni menempatkan kamu (di bumi. Kamu dirikan istana-istana di atas tanah-tanah yang datar) sebagai tempat tinggalmu di musim panas (dan kamu pahat gunung-gunungnya untuk dijadikan rumah) yang kamu tempati di musim dingin, dinashabkannya lafal buyuutan menjadi hal dari lafal yang tersimpan (maka ingatlah nikmat-nikmat Allah dan janganlah kamu merajalela di muka bumi membuat kerusakan).",[["وَٱذْكُرُوٓا۟","And remember"],["إِذْ","when"],["جَعَلَكُمْ","He made you"],["خُلَفَآءَ","successors"],["مِنۢ","from"],["بَعْدِ","after"],["عَادٍۢ","Aad"],["وَبَوَّأَكُمْ","and settled you"],["فِى","in"],["ٱلْأَرْضِ","the earth"],["تَتَّخِذُونَ","You take"],["مِن","from"],["سُهُولِهَا","its plains"],["قُصُورًۭا","palaces"],["وَتَنْحِتُونَ","and you carve out"],["ٱلْجِبَالَ","the mountains"],["بُيُوتًۭا ۖ","(as) homes"],["فَٱذْكُرُوٓا۟","So remember"],["ءَالَآءَ","(the) Bounties"],["ٱللَّهِ","(of) Allah"],["وَلَا","and (do) not"],["تَعْثَوْا۟","act wickedly"],["فِى","in"],["ٱلْأَرْضِ","(the) earth"],["مُفْسِدِينَ","spreading corruption"]]],"1029":["(Pemuka-pemuka yang menyombongkan diri di antara kaumnya berkata) maksudnya mereka yang sombong tidak mau beriman kepada Saleh (kepada orang-orang yang dianggap lemah yang telah beriman di antara mereka,) di antara kaumnya, menjadi badal dari lafal yang sebelumnya dengan mengulangi huruf jar (\"Tahukah kamu bahwa Saleh diutus menjadi rasul oleh Tuhannya?) kepadamu (Mereka menjawab,) 'Ya, betul.' (Sesungguhnya kami beriman kepada wahyu yang Saleh diutus untuk menyampaikannya.\")",[["قَالَ","Said"],["ٱلْمَلَأُ","the chiefs"],["ٱلَّذِينَ"," those"],["ٱسْتَكْبَرُوا۟","(who) were arrogant"],["مِن","among"],["قَوْمِهِۦ","his people"],["لِلَّذِينَ","to those who"],["ٱسْتُضْعِفُوا۟","were oppressed "],["لِمَنْ","[to] those who"],["ءَامَنَ","believed"],["مِنْهُمْ","among them"],["أَتَعْلَمُونَ","Do you know"],["أَنَّ","that"],["صَـٰلِحًۭا","Salih"],["مُّرْسَلٌۭ","(is the) one sent"],["مِّن","from"],["رَّبِّهِۦ ۚ","his Lord"],["قَالُوٓا۟","They said"],["إِنَّا","Indeed, we"],["بِمَآ","in what"],["أُرْسِلَ","he has been sent"],["بِهِۦ","with [it]"],["مُؤْمِنُونَ","(are) believers"]]],"1030":["(Orang-orang yang menyombongkan diri berkata, \"Sesungguhnya kami adalah orang yang tidak percaya kepada apa yang kamu imani itu.\")",[["قَالَ","Said"],["ٱلَّذِينَ","those who"],["ٱسْتَكْبَرُوٓا۟","were arrogant"],["إِنَّا","Indeed we"],["بِٱلَّذِىٓ","in that which"],["ءَامَنتُم","you believe"],["بِهِۦ","in it"],["كَـٰفِرُونَ","(are) disbelievers"]]],"1031":["Tersebutlah bahwa bagi unta betina itu satu hari minum, dan untuk mereka satu hari lainnya, akhirnya mereka bosan dengan ketentuan itu. (Kemudian mereka sembelih unta betina itu) yang melakukannya adalah orang yang terkuat berdasarkan perintah dari mereka, yaitu ia diperintahkan agar menyembelihnya dengan pedangnya (dan mereka berlaku angkuh terhadap perintah Tuhan. Dan mereka berkata, \"Hai Saleh! Datangkanlah apa yang kamu ancamkan itu kepada kami) yakni azab sebagai balasan atas pembunuhan unta itu (jika betul kamu termasuk orang yang diutus Allah.\").",[["فَعَقَرُوا۟","Then they hamstrung"],["ٱلنَّاقَةَ","the she-camel"],["وَعَتَوْا۟","and (were) insolent"],["عَنْ","towards"],["أَمْرِ","(the) command"],["رَبِّهِمْ","(of) their Lord"],["وَقَالُوا۟","and they said"],["يَـٰصَـٰلِحُ","O Salih"],["ٱئْتِنَا","Bring us"],["بِمَا","what"],["تَعِدُنَآ","you promise us"],["إِن","if"],["كُنتَ","you are"],["مِنَ","of"],["ٱلْمُرْسَلِينَ","the Messengers"]]],"1032":["(Karena itu mereka ditimpa gempa) gempa bumi yang keras beserta suara gemuruh dari langit (maka jadilah mereka mayat-mayat yang bergelimpangan di tempat tinggal mereka) mereka mati dalam keadaan bertekuk-lutut.",[["فَأَخَذَتْهُمُ","So seized them"],["ٱلرَّجْفَةُ","the earthquake"],["فَأَصْبَحُوا۟","then they became"],["فِى","in"],["دَارِهِمْ","their homes"],["جَـٰثِمِينَ","fallen prone"]]],"1033":["(Maka Saleh berpaling) ia meninggalkan (mereka seraya berkata, \"Hai kaumku! Sesungguhnya aku telah menyampaikan kepadamu amanat Tuhanku dan aku telah memberi nasihat kepadamu tetapi kamu tidak menyukai orang-orang yang memberi nasihat.\")",[["فَتَوَلَّىٰ","So he turned away"],["عَنْهُمْ","from them"],["وَقَالَ","and he said"],["يَـٰقَوْمِ","O my people"],["لَقَدْ","Verily"],["أَبْلَغْتُكُمْ","I have conveyed to you"],["رِسَالَةَ","(the) Message"],["رَبِّى","(of) my Lord"],["وَنَصَحْتُ","and [I] advised"],["لَكُمْ","[to] you"],["وَلَـٰكِن","but"],["لَّا","not"],["تُحِبُّونَ","you like"],["ٱلنَّـٰصِحِينَ","the advisers"]]],"1034":["(Dan) ingatlah (Luth) kemudian disebutkan badalnya yaitu, (tatkala dia berkata kepada kaumnya, \"Mengapa kamu mengerjakan perbuatan fahisyah itu) yakni mendatangi dubur/anus laki-laki (yang belum pernah dikerjakan oleh seorang pun di dunia ini sebelummu?\") dari kalangan manusia dan jin.",[["وَلُوطًا","And Lut"],["إِذْ","when"],["قَالَ","he said"],["لِقَوْمِهِۦٓ","to his people"],["أَتَأْتُونَ","Do you commit"],["ٱلْفَـٰحِشَةَ","(such) immorality"],["مَا","not"],["سَبَقَكُم","has preceded you"],["بِهَا","therein"],["مِنْ","any"],["أَحَدٍۢ","one"],["مِّنَ","of"],["ٱلْعَـٰلَمِينَ","the worlds"]]],"1035":["(Tiada lain kamu itu) dengan menetapkan dua hamzah yang ditashilkan nomor duanya serta memasukkan alif di antara keduanya, menurut dua bacaan (mendatangi lelaki untuk melepaskan nafsumu kepada mereka bukan kepada wanita, melainkan kamu itu adalah orang-orang yang melampaui batas) melewati batas kehalalan menuju kepada keharaman.",[["إِنَّكُمْ","Indeed, you"],["لَتَأْتُونَ","you approach"],["ٱلرِّجَالَ","the men"],["شَهْوَةًۭ","lustfully"],["مِّن","from"],["دُونِ","instead of"],["ٱلنِّسَآءِ ۚ","the women"],["بَلْ","Nay"],["أَنتُمْ","you"],["قَوْمٌۭ","(are) a people"],["مُّسْرِفُونَ","(who) commit excesses"]]],"1036":["(Jawab kaumnya tidak lain hanya mengatakan, \"Usirlah mereka) Luth dan pengikut-pengikutnya (dari kotamu ini; sesungguhnya mereka adalah orang-orang yang berpura-pura menyucikan diri.\") dari mendatangi dubur laki-laki/homosek.",[["وَمَا","And not"],["كَانَ","was"],["جَوَابَ","(the) answer"],["قَوْمِهِۦٓ","(of) his people"],["إِلَّآ","except"],["أَن","that"],["قَالُوٓا۟","they said"],["أَخْرِجُوهُم","Drive them out"],["مِّن","of"],["قَرْيَتِكُمْ ۖ","your town"],["إِنَّهُمْ","Indeed, they"],["أُنَاسٌۭ","(are) people"],["يَتَطَهَّرُونَ","who keep themselves pure"]]],"1037":["(Kemudian Kami selamatkan dia dan pengikut-pengikutnya kecuali istrinya; dia termasuk orang-orang yang tertinggal) yang ikut binasa oleh azab Allah.",[["فَأَنجَيْنَـٰهُ","So We saved him"],["وَأَهْلَهُۥٓ","and his family"],["إِلَّا","except"],["ٱمْرَأَتَهُۥ","his wife"],["كَانَتْ","she was"],["مِنَ","of"],["ٱلْغَـٰبِرِينَ","those who stayed behind"]]],"1038":["(Dan Kami turunkan kepada mereka hujan) yakni hujan batu dari neraka Sijjiil kemudian membinasakan mereka (maka perhatikanlah bagaimana kesudahan orang-orang yang berdosa.)",[["وَأَمْطَرْنَا","And We showered"],["عَلَيْهِم","upon them"],["مَّطَرًۭا ۖ","a rain"],["فَٱنظُرْ","So see"],["كَيْفَ","how"],["كَانَ","was"],["عَـٰقِبَةُ","(the) end"],["ٱلْمُجْرِمِينَ","(of) the criminals"]]],"1039":["(Dan) Kami telah mengutus (kepada penduduk Madyan saudara mereka Syuaib. Ia berkata, \"Hai kaumku, sembahlah Allah, sekali-kali tidak ada Tuhan bagimu selain-Nya. Sesungguhnya telah datang kepadamu bukti yang nyata) yakni mukjizat (dari Tuhanmu) yang membenarkan kerasulanku (Maka sempurnakanlah) genapkanlah (takaran dan timbangan dan janganlah kamu kurangkan) maksudnya menekorkan (bagi manusia barang-barang takaran dan timbangan mereka dan janganlah kamu membuat kerusakan di muka bumi) dengan kekafiran dan maksiat-maksiat (sesudah Tuhan memperbaikinya) dengan mengutus rasul-rasul-Nya (Yang demikian itu) yang telah disebutkan itu (lebih baik bagimu jika betul-betul kamu orang-orang yang beriman) yang menghendaki keimanan, maka bersegeralah kamu kepada keimanan.",[["وَإِلَىٰ","And to"],["مَدْيَنَ","Madyan"],["أَخَاهُمْ","his brother"],["شُعَيْبًۭا ۗ","Shuaib"],["قَالَ","He said"],["يَـٰقَوْمِ","O my people"],["ٱعْبُدُوا۟","Worship"],["ٱللَّهَ","Allah"],["مَا","not"],["لَكُم","for you"],["مِّنْ","any"],["إِلَـٰهٍ","god"],["غَيْرُهُۥ ۖ","other than Him"],["قَدْ","Verily"],["جَآءَتْكُم","has came to you"],["بَيِّنَةٌۭ","a clear proof"],["مِّن","from"],["رَّبِّكُمْ ۖ","your Lord"],["فَأَوْفُوا۟","So give full"],["ٱلْكَيْلَ","[the] measure"],["وَٱلْمِيزَانَ","and the weight"],["وَلَا","and (do) not"],["تَبْخَسُوا۟","deprive"],["ٱلنَّاسَ","[the] people"],["أَشْيَآءَهُمْ","in their things"],["وَلَا","and (do) not"],["تُفْسِدُوا۟","cause corruption"],["فِى","in"],["ٱلْأَرْضِ","the earth"],["بَعْدَ","after"],["إِصْلَـٰحِهَا ۚ","its reformation"],["ذَٰلِكُمْ","That"],["خَيْرٌۭ","(is) better"],["لَّكُمْ","for you"],["إِن","if"],["كُنتُم","you are"],["مُّؤْمِنِينَ","believers"]]],"1040":["(Dan janganlah kamu duduk di tiap-tiap jalan) yakni tempat orang berlalu lintas (dengan menakut-nakuti) membuat orang-orang takut untuk melewatinya karena takut pakaian mereka diambil atau dikenakan pajak (dan menghalang-halangi) menghambat (dari jalan Allah) agama-Nya (terhadap orang yang beriman kepada-Nya) dengan cara kamu mengancam akan membunuhnya (dan kamu menginginkan agar jalan Allah itu) kamu menghendaki agar jalan itu (menjadi bengkok) tidak lurus (Dan ingatlah di waktu dahulunya kamu berjumlah sedikit, kemudian Allah membuat kamu menjadi banyak, lalu perhatikanlah bagaimana kesudahan orang-orang yang berbuat kerusakan\") sebelum kamu, oleh karena mereka mendustakan rasul-rasul mereka; yakni akhir dari perkara mereka ialah kebinasaan.",[["وَلَا","And (do) not"],["تَقْعُدُوا۟","sit"],["بِكُلِّ","on every"],["صِرَٰطٍۢ","path"],["تُوعِدُونَ","threatening"],["وَتَصُدُّونَ","and hindering"],["عَن","from"],["سَبِيلِ","(the) way"],["ٱللَّهِ","(of) Allah"],["مَنْ","(those) who"],["ءَامَنَ","believe"],["بِهِۦ","in Him"],["وَتَبْغُونَهَا","and seeking (to make) it"],["عِوَجًۭا ۚ","crooked"],["وَٱذْكُرُوٓا۟","And remember"],["إِذْ","when"],["كُنتُمْ","you were"],["قَلِيلًۭا","few"],["فَكَثَّرَكُمْ ۖ","and He increased you"],["وَٱنظُرُوا۟","And see"],["كَيْفَ","how"],["كَانَ","was"],["عَـٰقِبَةُ","(the) end"],["ٱلْمُفْسِدِينَ","(of) the corrupters"]]],"1041":["(Jika ada segolongan daripada kamu beriman kepada apa yang aku diutus untuk menyampaikannya, dan ada pula segolongan yang tidak beriman) terhadapnya (maka bersabarlah kamu) artinya kamu harap menunggu (hingga Allah menetapkan hukum-Nya di antara kita) antara kami dan kamu, dengan menyelamatkan yang hak dan menghancurkan yang batil (dan Dia adalah hakim yang sebaik-baiknya) yang paling adil.",[["وَإِن","And if"],["كَانَ","(there) is"],["طَآئِفَةٌۭ","a group"],["مِّنكُمْ","among you"],["ءَامَنُوا۟","(who has) believed"],["بِٱلَّذِىٓ","in that which"],["أُرْسِلْتُ","I have been sent"],["بِهِۦ","with [it]"],["وَطَآئِفَةٌۭ","and a group"],["لَّمْ","not"],["يُؤْمِنُوا۟","they believe"],["فَٱصْبِرُوا۟","then be patient"],["حَتَّىٰ","until"],["يَحْكُمَ","judges"],["ٱللَّهُ","Allah"],["بَيْنَنَا ۚ","between us"],["وَهُوَ","And He"],["خَيْرُ","(is the) Best"],["ٱلْحَـٰكِمِينَ","(of) [the] Judges"]]]});